      if(OBS){var rs=OBS.takeRecords();if(rs.length){var was=DRAW.slice();Promise.resolve().then(function(){was.forEach(function(f){try{f(rs);}catch(e){DIAG.note(e,'screen:afterDraw');}});});}}
