/* ================= diagnostics log =================
   Errors the app catches on purpose and carries on from used to vanish in empty catch blocks.
   They are counted per code location; see Help & About → Diagnostics. Nothing leaves the device. */
var DIAG=(function(){
  var sites=Object.create(null),total=0;
  function note(e,site){
    try{total++;var s=sites[site]||(sites[site]={site:site,count:0,msg:''});s.count++;s.last=Date.now();s.msg=String((e&&e.message)||e||'').slice(0,200);}
    catch(_){/* the logger itself must never throw */}
  }
  return {note:note,total:function(){return total;},
    list:function(){return Object.keys(sites).map(function(k){return sites[k];}).sort(function(a,b){return b.count-a.count;});}};
})();
/* ================= action registry =================
   Every tap on an element with data-act="…" goes through ACT.dispatch.
   Modules register with ACT.on(module,{action:function(el,next){…}}).
   · the newest registration runs first;
   · a handler that also wants the older behaviour calls next(el); one that does not, replaces it;
   · ACT.list() shows which modules handle each action, newest first. */
var ACT=(function(){
  var H=Object.create(null);
  function on(mod,map){for(var k in map)if(Object.prototype.hasOwnProperty.call(map,k))(H[k]=H[k]||[]).push({fn:map[k],mod:mod});}
  function run(list,i,el){
    var h=list[i];if(!h)return;
    return h.fn(el,function(e2){
      if(!e2||e2===el)return run(list,i-1,el);
      var a2=e2.dataset&&e2.dataset.act,a1=el&&el.dataset&&el.dataset.act;
      return a2===a1?run(list,i-1,e2):dispatch(e2);
    });
  }
  function dispatch(el){var a=el&&el.dataset?el.dataset.act:undefined,list=a!=null?H[a]:null;if(list)return run(list,list.length-1,el);}
  function list(){var o={};Object.keys(H).sort().forEach(function(k){o[k]=H[k].map(function(h){return h.mod;}).reverse();});return o;}
  return {on:on,dispatch:dispatch,list:list};
})();
