var DEF_CATS={Expense:['Food & Dining','Groceries','Transport','Bills & Utilities','Shopping','Health','Entertainment','Education','Rent & Housing','Travel','Personal Care','Others'],Income:['Salary','Bonus','Business','Investment','Gift','Others']};
