var DB=null;
function defaultDB(){
  return {version:4,people:['Me'],accTypes:['Cash','Bank','Card','eWallet'],accTypeMeta:{},accounts:[{name:'Cash',start:0,owner:'',type:'Cash'},{name:'Bank',start:0,owner:'',type:'Bank'}],
    categories:JSON.parse(JSON.stringify(DEF_CATS)),subcats:{},txns:[],recur:[],
    budgets:{},fixedCats:[],
    meta:{changedAt:0,pushedAt:0,currency:'RM',accent:'',mode:''}};
}
function normalizeDB(){
  if(!DB.subcats||typeof DB.subcats!=='object'||Array.isArray(DB.subcats))DB.subcats={};
  if(!DB.budgets||typeof DB.budgets!=='object'||Array.isArray(DB.budgets))DB.budgets={};
  if(!Array.isArray(DB.fixedCats))DB.fixedCats=[];
  if(!DB.accTypeMeta||typeof DB.accTypeMeta!=='object'||Array.isArray(DB.accTypeMeta))DB.accTypeMeta={};
  /* v1.15: a billing cycle only makes sense on debt types — scrubbed everywhere else */
  Object.keys(DB.accTypeMeta).forEach(function(k){var m=DB.accTypeMeta[k]||{};m.kind=(m.kind==='liability')?'liability':'asset';var d=parseInt(m.cycle,10);m.cycle=(m.kind==='liability'&&d>=1&&d<=31)?d:0;DB.accTypeMeta[k]=m;});
  if(!Array.isArray(DB.accTypes)||!DB.accTypes.length)DB.accTypes=['Cash','Bank','Card','eWallet'];
  DB.accTypes=DB.accTypes.map(function(t){return String(t||'').trim();}).filter(function(t,i,a){return t&&a.indexOf(t)===i;});
  if(!DB.accTypes.length)DB.accTypes=['Cash'];
  DB.accounts.forEach(function(a){
    if(typeof a.owner!=='string')a.owner='';
    if(typeof a.start!=='number'||!isFinite(a.start))a.start=0;
    if(!a.type||DB.accTypes.indexOf(a.type)<0)a.type=DB.accTypes[0];
    var cy=parseInt(a.cycle,10);a.cycle=(accTypeKind(a.type)==='liability'&&cy>=1&&cy<=31)?cy:0; /* v1.15: cycles survive only on debt accounts */
    /* v1.12: receivable accounts are recognised by their “X owes Y” name */
    if(/^.+ owes .+$/.test(String(a.name))){
      a.recv=1;
      var rpp=String(a.name).split(' owes '); /* v1.17: debt ledgers are jointly owned by both sides */
      a.owner=(rpp.length===2)?jointPair(rpp[0],rpp[1]):(a.owner||'');
      if(DB.accTypes.indexOf('Between Us')<0){DB.accTypes.push('Between Us');DB.accTypeMeta['Between Us']={kind:'asset',cycle:0};}
    }else if(a.recv)delete a.recv;
  });
  DB.txns.forEach(function(t){
    if(typeof t.to!=='string')t.to='';
    /* v1.17: an owed mark is only kept when the ledger exists and the signed entry is real */
    if(t.owedAcc){
      var od=Math.round(+t.owedAmt*100)/100;
      if(!DB.accounts.some(function(a){return a.name===t.owedAcc;})||!isFinite(od)||!od){t.owedAcc='';t.owedAmt=0;}
      else t.owedAmt=od;
    }
  });
  if(!Array.isArray(DB.recur))DB.recur=[];
  DB.recur=DB.recur.filter(function(r){return r&&r.id&&r.tpl&&['day','week','month','year'].indexOf(r.freq)>=0&&/^\d{4}-\d{2}-\d{2}$/.test(r.anchor||'')&&/^\d{4}-\d{2}-\d{2}$/.test(r.next||'');});
  DB.recur.forEach(function(r){var e=parseInt(r.every,10);r.every=(e>=1)?e:1;r.seq=Math.max(0,parseInt(r.seq,10)||0);});
}
function loadDB(){
  try{
    var raw=(typeof V57!=='undefined'&&V57.pre!=null)?V57.pre:localStorage.getItem(LS_KEY);
    if(raw){
      var d=JSON.parse(raw);
      if(d&&Array.isArray(d.txns)){
        DB=Object.assign(defaultDB(),d);
        DB.categories=Object.assign(JSON.parse(JSON.stringify(DEF_CATS)),d.categories||{});
        DB.meta=Object.assign({changedAt:0,pushedAt:0,currency:'RM',accent:'',mode:''},d.meta||{});
        normalizeDB();
        explodeSplits();
        return;
      }
    }
  }catch(e){console.warn('load failed',e);}
  DB=defaultDB();
}
