function setSel(id,val,fb){
  var s=$(id);
  var has=false,os=s.options,i;
  for(i=0;i<os.length;i++){if(os[i].value===val){has=true;break;}}
  if(has){s.value=val;return val;}
  s.value=fb;return fb;
}
