function subList(c){if(!DB.subcats||typeof DB.subcats!=='object')DB.subcats={};if(!DB.subcats[c])DB.subcats[c]=[];return DB.subcats[c];}
function mgrRow(lb,sub,editAttrs,delAttrs,amt){
  return '<div class="mgr-row"><span class="lb">'+lb+'<small>'+sub+'</small></span>'
    +(amt?'<span class="mamt">'+amt+'</span>':'')
    +'<button class="ibtn" data-act="mgredit" '+(editAttrs||'')+' aria-label="edit">'+ico('pencil')+'</button>'
    +'<button class="ibtn" data-act="mgrdel" '+(delAttrs||'')+' aria-label="delete" style="color:var(--exp)">'+ico('trash')+'</button></div>';
}
function mgrEditRow(i,val,saveAttrs){
  return '<div class="mgr-row"><input class="fin" id="mgrN'+i+'" value="'+esc(val)+'" style="flex:1;padding:8px 10px;font-size:var(--fs-14);min-width:0">'
    +'<button class="ibtn" data-act="mgrsave" '+(saveAttrs||'')+' style="color:var(--inc)">Save</button>'
    +'<button class="ibtn" data-act="mgrcancel" aria-label="cancel">'+ico('x')+'</button></div>';
}
function ownerOptions(sel){
  if(isCollabMode()){var me=collabCfg().me;return '<option'+(sel===me||!sel?' selected':'')+'>'+esc(me)+'</option>'+(sel&&sel!==me?'<option selected>'+esc(sel)+'</option>':'');}
  var h='<option value="">— No account owner —</option>'+sortedAlpha(DB.people).map(function(p){return '<option'+(sel===p?' selected':'')+'>'+esc(p)+'</option>';}).join('');
  if(sel&&DB.people.indexOf(sel)<0)h+='<option selected>'+esc(sel)+'</option>'; /* v1.17: keep joint / stale account owners visible */
  return h;
}
function recurKey(r){
  var d=r.tpl||{};
  var k=(d.type==='Transfer')?'transfer':String(d.category||'');
  return k.toLowerCase()+'\u0000'+String(d.type==='Transfer'?'':(d.person||'')).toLowerCase();
}
function renderRecurMgr(){
  var h='';
  h+=DB.recur.length?DB.recur.slice().sort(function(a,b){var ka=recurKey(a),kb=recurKey(b);return ka<kb?-1:ka>kb?1:0;}).map(function(r){
    var d=r.tpl||{},every=r.every||1;
    var unit=r.freq==='day'?(every>1?'days':'day'):r.freq==='week'?(every>1?'weeks':'week'):r.freq==='month'?(every>1?'months':'month'):(every>1?'years':'year');
    var lb=(d.type==='Transfer'?'⇄ ':d.type==='Income'?'+ ':'− ')+money(d.amount||0)+' · '+(d.type==='Transfer'?'Transfer':esc(d.category||'—'));
    var sub='every '+every+' '+unit+' · '+(d.type==='Transfer'?(esc(d.account||'—')+' → '+esc(d.to||'?')):(esc(d.account||'—')+' · '+esc(d.person||'—')))+' · next '+(r.next?dLabelYW(r.next):'—');
    return mgrRow(lb,sub,'data-k="'+esc(r.id)+'"','data-k="'+esc(r.id)+'"');
  }).join(''):'<div class="help" style="padding:8px 2px">No recurring transactions yet. Set '+ico('repeat')+' Repeat on any transaction to start one.</div>';
  $('mgrBody').innerHTML=h;
}
function pickFilter(v){v=String(v||'').toLowerCase();var rs=document.querySelectorAll('#mgrBody .pkrow'),n=0;for(var i=0;i<rs.length;i++){var on=rs[i].dataset.q.indexOf(v)>=0;rs[i].hidden=!on;if(on)n++;}var e=$('pkNone');if(e)e.hidden=n>0;var ad=$('mgrNew');if(ad&&v&&!ad.dataset.touched)ad.value=$('pkSearch').value;}
function pickList(items,sel,act,attr){
  return '<input class="fin" id="pkSearch" placeholder="Search…" oninput="pickFilter(this.value)" style="margin-bottom:8px">'
    +'<div class="dayg pk" style="max-height:46vh;overflow-y:auto">'+items.map(function(c){return '<button class="txn pkrow" data-q="'+esc(String(c).toLowerCase())+'" data-act="'+act+'" '+attr+'="'+esc(c)+'"><span class="mid"><b>'+esc(c)+'</b></span>'+(c===sel?'<span class="pos">'+ico('check')+'</span>':'')+'</button>';}).join('')
    +'<div class="help small" id="pkNone" hidden style="padding:10px 12px">No match. Add it below.</div></div>';
}
function renderPickCat(){
  var cats=sortedAlpha(DB.categories[F.type]||[]);
  $('mgrTitle').innerHTML=ico('tag')+' '+(F.type==='Income'?'Income':'Expense')+' categories';
  $('mgrBody').innerHTML=pickList(cats,F.cat,'pickcat','data-c')
    +'<div class="mgr-add"><div class="mgr-lb">Add a new '+(F.type==='Income'?'income':'expense')+' category</div><div style="display:flex;gap:7px"><input class="fin" id="mgrNew" placeholder="e.g. Pets" oninput="this.dataset.touched=1" style="flex:1"><button class="ibtn" data-act="catadd2" style="color:var(--accent);font-weight:800">Add</button></div></div>';
}
function renderPickSub(){
  var subs=sortedAlpha(subList(F.cat));
  $('mgrTitle').innerHTML=ico('list')+' '+esc(F.cat)+' · sub-categories';
  $('mgrBody').innerHTML=(subs.length?pickList(['(None)'].concat(subs),F.sub||'(None)','picksub','data-s'):'<div class="help small" style="margin-bottom:8px">No sub-categories for '+esc(F.cat)+' yet.</div>')
    +'<div class="mgr-add"><div class="mgr-lb">Add a new sub-category</div><div style="display:flex;gap:7px"><input class="fin" id="mgrNew" placeholder="e.g. Restaurant" oninput="this.dataset.touched=1" style="flex:1"><button class="ibtn" data-act="subadd" style="color:var(--accent);font-weight:800">Add</button></div></div>';
}
function catAddFromPicker(){
  var n=(($('mgrNew')||{}).value||'').trim();
  if(!n){toast('Enter a category name');return;}
  var list=DB.categories[F.type]=DB.categories[F.type]||[];
  var hit=list.find(function(c){return c.toLowerCase()===n.toLowerCase();});
  if(!hit){list.push(n);hit=n;}
  F.cat=hit;F.sub='';renderFormCats(F.cat);touch();closeMgr();toast(hit===n?'Category “'+n+'” added ✓':'Selected existing “'+hit+'”');
}
function subAddFromPicker(){
  var n=(($('mgrNew')||{}).value||'').trim();
  if(!n){toast('Enter a sub-category name');return;}
  if(subList(F.cat).indexOf(n)<0)subList(F.cat).push(n);
  F.sub=n;renderFormCats(F.cat);
  touch();closeMgr();toast('Sub-category “'+n+'” added ✓');
}
function mgrAdd(){
  var n=(($('mgrNew')||{}).value||'').trim();
  if(MGR.kind==='people')return addPerson(n);
  if(MGR.kind==='cats')return addCategory(n,$('mgrNewType')?$('mgrNewType').value:'Expense');
  if(MGR.kind==='subs')return addSub($('mgrNewSubCat')?$('mgrNewSubCat').value:'',n);
  if(MGR.kind==='accs')return addAccountMgr();
  if(MGR.kind==='acctype')return addAccType(n,$('mgrNewKind')?$('mgrNewKind').value:'');
}
function mgrDel(k){
  if(MGR.kind==='people')return delPerson(k);
  if(MGR.kind==='cats'){var i=k.indexOf(':');return delCategory(k.slice(0,i),k.slice(i+1));}
  if(MGR.kind==='subs'){var p=k.split('::');return delSub(p[0],p[1]);}
  if(MGR.kind==='accs')return accDel(k);
  if(MGR.kind==='acctype')return delAccType(k);
  if(MGR.kind==='recur')return delRecur(k);
}
function mgrSave(el){
  var i=el.dataset.i,k=el.dataset.k||'',inp=$('mgrN'+i);
  var v=inp?inp.value:'';
  if(MGR.kind==='people')return renamePerson(k,v);
  if(MGR.kind==='cats'){var ci=k.indexOf(':'),mv=$('mgrMv'+i);if(mv&&mv.value)return mergeCategory(k.slice(0,ci),k.slice(ci+1),mv.value);return renameCategory(k.slice(0,ci),k.slice(ci+1),v);}
  if(MGR.kind==='subs'){var p=k.split('::'),mv2=$('mgrMv'+i);if(mv2&&mv2.value)return moveSubCat(p[0],p[1],mv2.value);return renameSub(p[0],p[1],v);}
  if(MGR.kind==='accs')return accSave(k);
  if(MGR.kind==='acctype')return saveAccType(k);
}
/* ===== account types (v1.7 with asset/debt + cycle) ===== */
function addAccType(n,kind){
  n=(n||'').trim();
  if(!n){toast('Enter a type name');return;}
  if(DB.accTypes.indexOf(n)>=0){toast('Already exists');return;}
  var kd=kind||'';
  if(kd!=='asset'&&kd!=='liability')kd=/card|credit/i.test(n)?'liability':'asset';
  DB.accTypes.push(n);
  DB.accTypeMeta[n]={kind:kd,cycle:0};
  touch();renderMgr();toast('Account type added ✓');
}
function saveAccType(oldN){
  var newName=(($('mgrEName')||{}).value||oldN).trim();
  var kind=$('mgrEKind')?$('mgrEKind').value:'asset';
  /* v1.27: the type editor no longer asks for a billing cycle (it lives on each account in
     Accounts → the account → Edit); the type keeps its own default */
  var cyc=accTypeCycle(oldN);
  if(kind!=='liability')cyc=0; /* v1.15 rule kept: cycles only live on debts */
  if(newName!==oldN){
    if(!newName){toast('Name required');return;}
    if(DB.accTypes.indexOf(newName)>=0){toast('Name already used');return;}
    var m=DB.accTypeMeta[oldN];delete DB.accTypeMeta[oldN];if(m)DB.accTypeMeta[newName]=m;
    DB.accTypes[DB.accTypes.indexOf(oldN)]=newName;
    DB.accounts.forEach(function(a){if(a.type===oldN)a.type=newName;}); /* v1.27 fix: was newN (undefined) — renaming a USED type crashed mid-save */
  }
  DB.accTypeMeta[newName]={kind:kind,cycle:cyc};
  MGR.edit=null;touch();renderMgr();toast('Type saved ✓');
}
function delAccType(ty){
  var used=0;DB.accounts.forEach(function(a){if(a.type===ty)used++;});
  if(used){toast('Used by '+used+' account'+(used>1?'s':'')+' — cannot delete');return;}
  if(DB.accTypes.length<=1){toast('Keep at least one account type');return;}
  askConfirm('Delete account type “'+ty+'”?','Delete',function(){
    var snap=snapLists(['accTypes','accTypeMeta']);
    DB.accTypes=DB.accTypes.filter(function(x){return x!==ty;});
    if(MGR.edit===ty)MGR.edit=null;
    touch();renderMgr();toastAct('Account type deleted — undo?',function(){undoRestoreLists(snap);});
  });
}
function addPerson(n){
  n=(n||'').trim();
  if(!n){toast('Enter a name');return;}
  if(DB.people.indexOf(n)>=0){toast('Already added');return;}
  DB.people.push(n);
  touch();renderMgr();toast(n+' added ✓');
}
function renamePerson(oldN,newN){
  newN=(newN||'').trim();
  if(!newN){toast('Name required');return;}
  if(newN===oldN){MGR.edit=null;renderMgr();return;}
  if(DB.people.indexOf(newN)>=0){toast('Name already used');return;}
  DB.people[DB.people.indexOf(oldN)]=newN;
  DB.txns.forEach(function(t){
    if(t.person===oldN)t.person=newN;
    if(hasSplit(t))t.split.forEach(function(s){if(s.p===oldN)s.p=newN;});
  });
  DB.accounts.forEach(function(a){
    if(a.owner===oldN)a.owner=newN;
    else if(a.owner&&String(a.owner).indexOf(' & ')>=0)a.owner=a.owner.split(' & ').map(function(x){return x===oldN?newN:x;}).join(' & '); /* v1.17: joint account owners */
    if(/^.+ owes .+$/.test(String(a.name))){ /* v1.17: keep ledger names + refs in sync */
      var pn=String(a.name).split(' owes ').map(function(x){return x===oldN?newN:x;}).join(' owes ');
      if(pn!==a.name){var on=a.name;a.name=pn;DB.txns.forEach(function(t){if(t.to===on)t.to=pn;if(t.owedAcc===on)t.owedAcc=pn;});}
    }
  });
  if(OV.person===oldN)OV.person=newN;
  TXF.who=TXF.who.map(function(p){return p===oldN?newN:p;});
  MGR.edit=null;touch();renderMgr();toast('Renamed to '+newN+' ✓');
}
function delPerson(n){
  var used=0;DB.txns.forEach(function(t){if(t.person===n)used++;});
  askConfirm(used?('“'+n+'” has '+used+' transactions. They keep the name label but the person disappears from pickers. Remove?'):('Remove “'+n+'”?'),'Remove',function(){
    var snap=snapLists(['people']);
    DB.people=DB.people.filter(function(p){return p!==n;});
    if(OV.person===n)OV.person='all';
    TXF.who=TXF.who.filter(function(p){return p!==n;});
    if(MGR.edit===n)MGR.edit=null;
    touch();renderMgr();toastAct('Removed '+n+' — undo?',function(){undoRestoreLists(snap);});
  });
}
function addCategory(n,ty){
  n=(n||'').trim();ty=ty||'Expense';
  if(!n){toast('Enter a category name');return;}
  if(DB.categories[ty].indexOf(n)>=0){toast('Already exists');return;}
  DB.categories[ty].push(n);
  touch();renderMgr();toast('Category added ✓');
}
function renameCategory(ty,oldN,newN){
  newN=(newN||'').trim();
  if(!newN){toast('Name required');return;}
  if(newN===oldN){MGR.edit=null;renderMgr();return;}
  if(DB.categories[ty].indexOf(newN)>=0){toast('Name already used');return;}
  DB.categories[ty][DB.categories[ty].indexOf(oldN)]=newN;
  DB.txns.forEach(function(t){if(t.type===ty&&t.category===oldN)t.category=newN;});
  if(DB.subcats&&DB.subcats[oldN]){DB.subcats[newN]=DB.subcats[oldN];delete DB.subcats[oldN];}
  if(F.cat===oldN)F.cat=newN;
  MGR.edit=null;touch();renderMgr();toast('Renamed to '+newN+' ✓');
}
function delCategory(ty,n){
  var used=0;
  DB.txns.forEach(function(x){if(x.type===ty&&x.category===n)used++;});
  if(used){toast(used+(used===1?' transaction uses':' transactions use')+' this category — move them first.',{type:'warn'});return;}
  askConfirm('Delete category “'+n+'”?','Delete',function(){
    var snap=snapLists(['categories','subcats']);
    DB.categories[ty]=DB.categories[ty].filter(function(c){return c!==n;});
    if(DB.subcats&&DB.subcats[n])delete DB.subcats[n];
    if(MGR.edit===ty+':'+n)MGR.edit=null;
    touch();renderMgr();toastAct('Category deleted — undo?',function(){undoRestoreLists(snap);});
  });
}
function addSub(c,n){
  n=(n||'').trim();
  if(!c){toast('Pick a category first');return;}
  if(!n){toast('Enter a sub-category name');return;}
  if(subList(c).indexOf(n)>=0){toast('Already exists');return;}
  subList(c).push(n);
  touch();renderMgr();toast('Sub-category added ✓');
}
function renameSub(c,oldN,newN){
  newN=(newN||'').trim();
  if(!newN){toast('Name required');return;}
  if(newN===oldN){MGR.edit=null;renderMgr();return;}
  if(subList(c).indexOf(newN)>=0){toast('Name already used');return;}
  subList(c)[subList(c).indexOf(oldN)]=newN;
  DB.txns.forEach(function(t){if(t.category===c&&t.subcategory===oldN)t.subcategory=newN;});
  MGR.edit=null;touch();renderMgr();toast('Renamed to '+newN+' ✓');
}
function delSub(c,s){
  var used=0;DB.txns.forEach(function(t){if(t.category===c&&t.subcategory===s)used++;});
  askConfirm('Delete sub-category “'+s+'” of '+c+'?'+(used?(' '+used+' transaction(s) keep the label, it just leaves the menu.'):''),'Delete',function(){
    var snap=snapLists(['subcats']);
    DB.subcats[c]=subList(c).filter(function(x){return x!==s;});
    if(!DB.subcats[c].length)delete DB.subcats[c];
    if(MGR.edit===c+'::'+s)MGR.edit=null;
    touch();renderMgr();toastAct('Sub-category deleted — undo?',function(){undoRestoreLists(snap);});
  });
}
/* ===== v1.23: CHANGE categories, not just rename — merge a category into another / move a sub-category ===== */
function mergeCategory(ty,from,to){
  if(!to||to===from){toast('Pick a different category');return;}
  var moved=0;DB.txns.forEach(function(t){if(t.type===ty&&t.category===from)moved++;});
  var nSub=(DB.subcats&&DB.subcats[from]?DB.subcats[from].length:0);
  askConfirm('Move '+moved+' transaction'+(moved===1?'':'s')+' of “'+from+'” into “'+to+'”'+(nSub?(' together with '+nSub+' sub-category'+(nSub===1?'':'s')):'')+'? “'+from+'” is removed after the move.','Move',function(){
    var sT=DB.txns.map(function(t){return Object.assign({},t);});
    var sC=JSON.parse(JSON.stringify(DB.categories));
    var sS=JSON.parse(JSON.stringify(DB.subcats||{}));
    DB.txns.forEach(function(t){if(t.type===ty&&t.category===from)t.category=to;});
    if(DB.subcats&&DB.subcats[from]){
      DB.subcats[to]=(DB.subcats[to]||[]).slice();
      DB.subcats[from].forEach(function(s){if(DB.subcats[to].indexOf(s)<0)DB.subcats[to].push(s);});
      delete DB.subcats[from];
    }
    DB.categories[ty]=DB.categories[ty].filter(function(x){return x!==from;});
    if(F.cat===from)F.cat=to;
    MGR.edit=null;touch();renderMgr();
    toastAct('Moved '+moved+' transaction'+(moved===1?'':'s')+' into '+to+' — undo?',function(){
      DB.txns=sT.map(function(t){return Object.assign({},t);});
      DB.categories=JSON.parse(JSON.stringify(sC));
      DB.subcats=JSON.parse(JSON.stringify(sS));
      MGR.edit=null;touch();renderMgr();toast('Merge undone');
    });
  });
}
function moveSubCat(from,sub,to){
  if(!to||to===from){toast('Pick a different category');return;}
  if(subList(to).indexOf(sub)>=0){toast('“'+sub+'” already exists under '+to);return;}
  var moved=0;DB.txns.forEach(function(t){if(t.category===from&&t.subcategory===sub){t.category=to;moved++;}});
  var fl=subList(from);fl.splice(fl.indexOf(sub),1);
  if(!fl.length)delete DB.subcats[from];
  subList(to).push(sub);
  if(F.cat===from&&F.sub===sub)F.cat=to;
  MGR.edit=null;touch();renderMgr();
  toast('“'+sub+'” moved to '+to+' · '+moved+' txn'+(moved===1?'':'s')+' updated ✓');
}
/* ===== v1.15: clear-data chooser — wipe everything or only the ticked manage lists ===== */
var CLR_LISTS=[
  {k:'txns',ic:'receipt',label:'Transactions',n:function(){return DB.txns.length;}},
  {k:'recur',ic:'repeat',label:'Recurring series',n:function(){return DB.recur.length;}},
  {k:'people',ic:'users',label:'People',n:function(){return DB.people.length;}},
  {k:'accs',ic:'card',label:'Accounts',n:function(){return DB.accounts.length;}},
  {k:'acctypes',ic:'folder',label:'Account types',n:function(){return DB.accTypes.length;}},
  {k:'cats',ic:'tag',label:'Categories & sub-categories',n:function(){var s=0;Object.keys(DB.subcats||{}).forEach(function(c){s+=(DB.subcats[c]||[]).length;});return (DB.categories.Expense||[]).length+(DB.categories.Income||[]).length+s;}}
];
function clearDataOpen(){
  $('clrBody').innerHTML=CLR_LISTS.slice().sort(function(a,b){return alphasort(a.label,b.label);}).map(function(L){
    return '<label style="display:flex;align-items:center;gap:10px;font-size:var(--fs-14);font-weight:600;padding:9px 10px;border:1px solid var(--line);border-radius:10px;cursor:pointer"><input type="checkbox" class="clrck" data-k="'+L.k+'" style="width:18px;height:18px;accent-color:var(--accent);flex:none"><span style="flex:1">'+ico(L.ic)+' '+L.label+'</span><span class="small" style="color:var(--muted)">'+L.n()+'</span></label>';
  }).join('')
    +'<div class="help small" style="margin-top:2px">Wiping Transactions keeps people, accounts and categories. Wiping Account types resets affected accounts to the first type. Recurring series re-add their due transactions on next launch unless wiped too.</div>';
  $('clrmodal').classList.add('on');
  navSync();
}
function clearLists(sel){
  var snap=snapLists(['txns','recur','people','accounts','accTypes','accTypeMeta','categories','subcats']);
  backupSnap('pre-clear'); /* wiped data stays recoverable from Backup history */
  if(sel.txns)DB.txns=[];
  if(sel.recur)DB.recur=[];
  if(sel.people)DB.people=[];
  if(sel.accs)DB.accounts=[];
  if(sel.acctypes){DB.accTypes=[];DB.accTypeMeta={};}
  if(sel.cats){DB.categories={Expense:[],Income:[]};DB.subcats={};}
  normalizeDB();
  DB.meta.changedAt=Date.now();save();renderAll();
  return snap;
}
function clearApply(wipeAll){
  var sel={};
  if(wipeAll){CLR_LISTS.forEach(function(L){sel[L.k]=1;});}
  else{
    var cks=document.querySelectorAll('#clrBody .clrck');
    for(var i=0;i<cks.length;i++){if(cks[i].checked)sel[cks[i].dataset.k]=1;}
  }
  var n=Object.keys(sel).length;
  if(!n){toast('Tick at least one list first — or use Wipe everything');return;}
  $('clrmodal').classList.remove('on');
  navSync();
  if(wipeAll)return clearAll(sel);
  var names=CLR_LISTS.filter(function(L){return sel[L.k];}).map(function(L){return L.label;}).join(', ');
  askConfirm('Clear '+n+' list'+(n>1?'s':'')+' on this device ('+names+')? A safety snapshot is kept in Backup history.','Clear '+n,function(){
    var snap=clearLists(sel);
    toastAct('Cleared: '+names+' — undo?',function(){undoRestoreLists(snap);});
  });
}
function clearAll(sel){
  askConfirm('Delete EVERYTHING on this device? The cloud file is NOT touched — the cloud link will be removed first so your Drive / OneDrive file stays safe.','Delete everything',function(){
    if(Cloud.handle){idbDel('handle');}
    Cloud.handle=null;Cloud.perm='unknown';
    var snap=clearLists(sel||{txns:1,recur:1,people:1,accs:1,acctypes:1,cats:1});
    toastAct('All local data wiped — undo?',function(){undoRestoreLists(snap);});
  });
}

/* ================= add / edit sheet ================= */
var F={id:null,type:'Expense',cat:'',sub:''};
var accOptions;
/* ===== v1.17: account-owner-driven transactions + cross-account-owner owed transfers =====
   The Paid-by picker is gone — a transaction's person is the ACCOUNT OWNER of the selected account.
   A transfer between two DIFFERENT account owners can be ticked “Amount owed”: on top of the two
   normal transfer legs it books a third entry into a JOINT debt ledger “<to-account-owner> owes
   <from-account-owner>” (shared by both people, so it can flip negative when the other side owes). */
function ownerOf(n){var a=DB.accounts.find(function(x){return x.name===n;});return (a&&a.owner)?a.owner:'';}
function jointPair(a,b){var x=[String(a||'').trim(),String(b||'').trim()].filter(Boolean);if(x.length<2)return '';return x.sort(alphasort).join(' & ');}
function ownerIco(o){return ico(String(o||'').indexOf(' & ')>=0?'users':'user');} /* v1.18: joint account owner → couple icon */
/* find or create the pair ledger for a cross-account-owner owed transfer:
   “<toOwner> owes <fromOwner>” takes +amt (the receiver now owes the sender);
   when the opposite-orientation ledger already exists it takes −amt (a repayment) */
function owedPairFor(from,to,amt){
  var fo=ownerOf(from),toO=ownerOf(to);
  var n1=toO+' owes '+fo,n2=fo+' owes '+toO;
  if(DB.accounts.some(function(a){return a.name===n1;}))return {name:n1,delta:amt};
  if(DB.accounts.some(function(a){return a.name===n2;}))return {name:n2,delta:-amt};
  ensureRecvAcc(n1);
  return {name:n1,delta:amt};
}
/* live Account owner display + Amount-owed checkbox wiring inside the transaction sheet */
function updateOwnerUI(){
  if(!$('fOwner'))return;
  var trf=F.type==='Transfer';
  var from=$('fAccount')?$('fAccount').value:'',to=(trf&&$('fTo'))?$('fTo').value:'';
  var fo=ownerOf(from),toO=to?ownerOf(to):'';
  /* v1.20: transfers show a separate account owner box beside EACH account — From account owner + To account owner */
  var box=$('fOwner');
  box.innerHTML=fo?(ownerIco(fo)+' '+esc(fo)):'<span style="opacity:.55">— no account owner</span>';
  var lb=$('fOwnerLbl');if(lb)lb.textContent=trf?'From account owner':'Account owner';
  var box2=$('fOwnerTo');
  if(box2)box2.innerHTML=trf?(toO?(ownerIco(toO)+' '+esc(toO)):'<span style="opacity:.55">— no account owner</span>'):'';
  var show=!!(trf&&fo&&toO&&fo!==toO&&!isRecvAcc(from)&&!isRecvAcc(to));
  $('fOwedRow').hidden=!show;
  if(!show){$('fOwedHint').innerHTML='';return;}
  var amt=parseAmt($('fAmount').value)||0;
  var ex2=DB.accounts.some(function(a){return a.name===fo+' owes '+toO;});
  var nm=ex2?(fo+' owes '+toO):(toO+' owes '+fo);
  var sg=ex2?'−':'+';
  $('fOwedHint').innerHTML='Entries on save: '+esc(from)+' <b class="neg">−'+money(amt)+'</b> · '+ico('bank')+' “'+esc(nm)+'” <b class="pos">'+sg+money(amt)+'</b> · '+esc(to)+' <b class="pos">+'+money(amt)+'</b>'+(ex2?' <span style="color:var(--muted)">(repays the debt)</span>':'');
}
function catFreq(ty){var m={};DB.txns.forEach(function(t){if(t.type===ty)m[t.category]=(m[t.category]||0)+1;});return m;}
/* v1.36: inline category + sub-category chips (most-used first) — no pop-up picker, no silent default */
function quickPick(all,sel,n){
  var q=all.slice(0,n);
  if(sel&&q.indexOf(sel)<0){q=[sel].concat(q.slice(0,n-1));}
  return q;
}
function renderFormCats(sel){
  var cats=DB.categories[F.type]||[];
  if(sel&&cats.indexOf(sel)<0)sel='';
  F.cat=sel||'';
  if(F.sub&&(!F.cat||subList(F.cat).indexOf(F.sub)<0))F.sub='';
  var fq=catFreq(F.type),ord=cats.slice().sort(function(a,b){return (fq[b]||0)-(fq[a]||0)||alphasort(a,b);});
  var q=quickPick(ord,F.cat,5);
  $('fCatChips').innerHTML=q.map(function(c){return '<button type="button" class="chip'+(c===F.cat?' on':'')+'" data-act="fcat" data-c="'+esc(c)+'">'+esc(c)+'</button>';}).join('')
    +'<button type="button" class="chip more" data-act="fcatmenu">'+ico('search')+' '+(cats.length>q.length?'All ('+cats.length+')':'More')+'</button>';
  $('fSub').value=F.sub||'';
  $('fSubRow').hidden=(F.type==='Transfer')||!F.cat;
  if(F.cat){
    var sf={};DB.txns.forEach(function(t){if(t.category===F.cat&&t.subcategory)sf[t.subcategory]=(sf[t.subcategory]||0)+1;});
    var subs=subList(F.cat).slice().sort(function(a,b){return (sf[b]||0)-(sf[a]||0)||alphasort(a,b);});
    var qs=quickPick(subs,F.sub,4);
    $('fSubChips').innerHTML='<button type="button" class="chip'+(!F.sub?' on':'')+'" data-act="fsubpick" data-s="">None</button>'
      +qs.map(function(x){return '<button type="button" class="chip'+(x===F.sub?' on':'')+'" data-act="fsubpick" data-s="'+esc(x)+'">'+esc(x)+'</button>';}).join('')
      +'<button type="button" class="chip more" data-act="fsubmenu">'+(subs.length>qs.length?ico('search')+' All ('+subs.length+')':ico('plus')+' New')+'</button>';
  }
}
function signUI(){var b=$('fSign');if(b)b.classList.toggle('on',F.type==='Expense'&&parseAmt($('fAmount').value)<0);}
function setFormType(t){
  F.type=t;
  var trf=t==='Transfer';
  $('segExp').className=t==='Expense'?'on-exp':'';
  $('segInc').className=t==='Income'?'on-inc':'';
  $('segTrf').className=trf?'on-trf':'';
  $('fSplitBox').hidden=trf;
  $('fCatBox').hidden=trf;
  $('fSubRow').hidden=trf;
  $('fToRow').hidden=!trf;
  $('fOwnerToRow').hidden=!trf; /* v1.20: the To-owner box lives beside To account */
  if($('fSign'))$('fSign').hidden=(t!=='Expense'); /* v1.24: ± sign flip only for expenses */
  $('fAccLabel').textContent=trf?'From account':'Account';
  
  if(trf){
    var pv=$('fTo').value,def=DB.accounts[1]?DB.accounts[1].name:(DB.accounts[0]?DB.accounts[0].name:'');
    $('fTo').innerHTML=accOptions(pv||def);
  }else{
    F.sub='';
    renderFormCats(F.id?'':((DB.meta.lastCat||{})[t]||''));
  }
  updateOwnerUI();
}
function openSheetRefresh(){if($('sheet').classList.contains('on'))$('fCur').textContent=cur();}
function dupTxn(){ /* v1.23: edit a copy — Save adds it as a NEW transaction */
  if(!F.id)return;
  var id=F.id;
  openSheet(id);
  F.id=null;
  $('sheetTitle').textContent='Duplicate transaction';
  $('btnDel').hidden=true;
  $('btnDup').hidden=true;
  toast('Editing a copy — tap Save to add it');
}
/* ===== recurring transactions (v1.9) ===== */
function repUI(){
  var f=$('fRep')?$('fRep').value:'',n=parseInt($('fRepEvery')?$('fRepEvery').value:'1',10);
  if(!(n>=1))n=1;
  var lb=$('fRepLbl');if(!lb)return;
  if(!f)lb.textContent='';
  else lb.textContent='every '+n+' '+(f==='day'?(n>1?'days':'day'):f==='week'?(n>1?'weeks':'week'):f==='month'?(n>1?'months':'month'):(n>1?'years':'year'));
  $('fRepEvery').style.display=f?'':'none';
  lb.style.display=f?'':'none';
}
/* attach/detach a recurring rule to the txn being saved (rec = form record, existing = old txn) */
function applyRepeat(rec,existing,skip){
  var freq=$('fRep')?$('fRep').value:'',every=parseInt($('fRepEvery')?$('fRepEvery').value:'1',10);
  if(!(every>=1))every=1;
  var oldRule=(existing&&existing.recur)?DB.recur.find(function(r){return r.id===existing.recur;}):null;
  if(!freq||skip){
    if(oldRule){DB.recur=DB.recur.filter(function(r){return r!==oldRule;});if(existing)delete existing.recur;}
    delete rec.recur;
    return;
  }
  if(!oldRule){
    var rid='r'+uid();
    oldRule={id:rid,tpl:{},freq:freq,every:every,anchor:rec.date,seq:0,next:advanceOcc(rec.date,freq,every,1)};
    DB.recur.push(oldRule);
    rec.recur=rid;
    if(existing)existing.recur=rid;
  }else{
    var ch=(oldRule.freq!==freq||oldRule.every!==every);
    oldRule.freq=freq;oldRule.every=every;
    rec.recur=oldRule.id;
    if(ch)oldRule.next=advanceOcc(oldRule.anchor,freq,every,(oldRule.seq||0)+1);
  }
  oldRule.tpl={date:rec.date,type:rec.type,category:rec.category,subcategory:rec.subcategory,account:rec.account,to:rec.to,person:rec.person,note:rec.note,amount:rec.amount,split:rec.split?JSON.parse(JSON.stringify(rec.split)):null,owedAcc:rec.owedAcc||'',owedAmt:rec.owedAmt||0};
}
function delRecur(rid){
  askConfirm('Stop this series? Past transactions are kept.','Stop series',function(){
    var snap=snapLists(['recur','txns']);
    DB.recur=DB.recur.filter(function(r){return r.id!==rid;});
    DB.txns.forEach(function(t){if(t.recur===rid)delete t.recur;});
    touch();renderMgr();toastAct('Recurring series stopped — undo?',function(){undoRestoreLists(snap);});
  });
}
function recurAnchorEdit(rid){
  var t=DB.txns.find(function(x){return x.recur===rid;});
  if(!t){toast('Original transaction was deleted — stop the series and create a new one');return;}
  closeMgr();openSheet(t.id);
}
/* ================= split editor (R2) ================= */
var SPLIT={rows:[]};
function nextSplitPerson(){
  var used={};SPLIT.rows.forEach(function(r){used[r.p]=1;});
  var free=DB.people.filter(function(x){return !used[x];});
  return free.length?free[0]:(DB.people[0]||'');
}
function renderSplitRows(){
  var box=$('fSplitRows');
  if(!DB.people||DB.people.length<2){box.innerHTML='<div class="help small">Add at least 2 people in Settings → Your Profile to split a transaction between them.</div>';updateSplitHint();return;}
  if(!SPLIT.rows.length){
    box.innerHTML='<button class="btn ghost" style="padding:10px;font-size:var(--fs-13)" data-act="splitadd">'+ico('users')+' Split between people</button>';
    updateSplitHint();return;
  }
  box.innerHTML=SPLIT.rows.map(function(r,i){
    var opts=sortedAlpha(DB.people).map(function(p){return '<option'+(p===r.p?' selected':'')+'>'+esc(p)+'</option>';}).join('');
    if(r.p&&DB.people.indexOf(r.p)<0)opts='<option selected>'+esc(r.p)+'</option>'+opts;
    var row='<div class="split-row"><select class="fin" data-si="'+i+'" data-sf="p" onchange="splitEdit(this)">'+opts+'</select>'
      +'<input class="fin" inputmode="decimal" value="'+esc(r.v)+'" data-si="'+i+'" data-sf="v" oninput="splitEdit(this)" placeholder="0.00">'
      +'<button class="ibtn" data-act="splitdel" data-i="'+i+'" aria-label="remove">'+ico('x')+'</button>';
    return row+'</div>';
  }).join('')
  +(DB.people.length>SPLIT.rows.length?'<button class="ibtn" data-act="splitadd" style="width:100%;text-align:center;margin-bottom:6px">'+ico('plus')+' Add person</button>':'')
  +'<button class="ibtn" data-act="spliteven" style="width:100%;text-align:center">'+ico('scale')+' Split equally</button>';
  updateSplitHint();
}
function splitEdit(el){
  var i=+el.dataset.si;
  if(!SPLIT.rows[i])return;
  if(el.dataset.sf==='p'){SPLIT.rows[i].p=el.value;renderSplitRows();}
  else{SPLIT.rows[i].v=el.value;updateSplitHint();}
}
function splitAdd(){var p=nextSplitPerson();SPLIT.rows.push({p:p,v:''});renderSplitRows();}
function splitDel(i){SPLIT.rows.splice(i,1);renderSplitRows();}
function splitEven(){
  var amt=Math.abs(parseAmt($('fAmount').value)); /* v1.37: refunds split by size too */
  if(!(amt>0)){toast('Enter the amount first');return;}
  var n=SPLIT.rows.length;
  if(!n)return;
  var each=Math.floor(amt/n*100)/100;
  SPLIT.rows.forEach(function(r,i){r.v=(i===n-1)?Math.round((amt-each*(n-1))*100)/100:each;});
  renderSplitRows();
}
function splitRowsClean(){
  var rows=[],seen={};
  SPLIT.rows.forEach(function(r){
    var v=Math.round(Math.abs(parseAmt(r.v))*100)/100,p=(r.p||'').trim(); /* v1.37: shares are sizes — the sign follows the amount */
    if(!(v>0)||!p)return;
    if(seen[p]){rows=rows.map(function(x){if(x.p===p)x.v=Math.round((x.v+v)*100)/100;return x;});}
    else{seen[p]=1;rows.push({p:p,v:v});}
  });
  return rows;
}
function updateSplitHint(){
  var h=$('fSplitHint');
  if(!h)return;
  if(!SPLIT.rows.length){h.textContent='';return;}
  var raw=parseAmt($('fAmount').value),amt=Math.abs(raw),sum=0;
  var refund=F.type==='Expense'&&raw<0,inc=F.type==='Income',incRed=inc&&raw<0;
  SPLIT.rows.forEach(function(r){sum+=Math.abs(parseAmt(r.v));});
  var left=Math.round((amt-sum)*100)/100;
  var kind=refund?'refund':(inc?'income':'bill');
  if(left>0.004){h.textContent='Unassigned: '+money(left)+' of the '+money(amt)+' '+kind+' — goes to the account owner';h.style.color='var(--warn)';}
  else if(left<-0.004){h.textContent='Over by '+fmt(-left)+' — shares exceed the '+kind+' amount';h.style.color='var(--exp)';}
  else{
    var payer=ownerOf(($('fAccount')&&$('fAccount').value)||'')||DB.people[0]||'Me';
    var dbt=SPLIT.rows.map(function(r){return {p:(r.p||'').trim(),v:Math.abs(parseAmt(r.v))};}).filter(function(x){return x.p&&x.p!==payer&&x.v>0;});
    var eff=dbt.map(function(d){
      if(refund)return esc(d.p)+' owes '+esc(payer)+' '+money(d.v)+' less';
      if(incRed)return esc(payer)+' owes '+esc(d.p)+' '+money(d.v)+' less';
      if(inc)return esc(payer)+' owes '+esc(d.p)+' '+money(d.v)+' (their share)';
      return esc(d.p)+' owes '+esc(payer)+' '+money(d.v);
    });
    h.innerHTML=ico('check')+' Shares add up to the '+money(amt)+' '+kind+(eff.length?' · '+eff.join(', '):'');
    h.style.color='var(--inc)';
  }
}
/* v1.24: ± flips the amount sign — for Expense a negative amount is a REDUCTION in expenses, not income */
function flipSign(){
  var el=$('fAmount');if(!el)return;
  if(F.type!=='Expense'){toast('Negative amounts apply to Expense — they reduce the expense');return;}
  var v=parseAmt(el.value);
  if(!v){toast('Type the amount first');return;}
  el.value=String(Math.round(-v*100)/100);
  updateSplitHint();updateOwnerUI();signUI();
  toast(parseAmt(el.value)<0?'Recorded as a refund (reduces expenses)':'Back to a normal expense');
}
/* every transaction created by one split bill shares a group id (v1.12 legs) */
function splitGroupTxns(id){
  var t=DB.txns.find(function(x){return x.id===id;});
  if(!t||!t.group)return null;
  return DB.txns.filter(function(x){return x.group===t.group;});
}
function delTxn(){
  if(!F.id)return;
  var id=F.id;
  var legs=splitGroupTxns(id); /* v1.15: deleting a split bill removes ALL its legs */
  askConfirm(legs?('Delete this whole split bill? All '+legs.length+' related transactions (every leg of the split) will be removed.'):'Delete this transaction?',legs?('Delete all '+legs.length):'Delete',function(){
    var snaps=[];
    if(legs){
      var g=legs[0].group;
      legs.forEach(function(t){snaps.push(Object.assign({},t));});
      DB.txns=DB.txns.filter(function(x){return x.group!==g;});
    }else{
      var snap=null;
      DB.txns.forEach(function(t){if(t.id===id)snap=Object.assign({},t);});
      if(snap)snaps.push(snap);
      DB.txns=DB.txns.filter(function(x){return x.id!==id;});
    }
    closeSheet();touch();
    toastAct(snaps.length>1?('Deleted '+snaps.length+' transactions — undo?'):('Deleted'+(snaps[0]?' '+money(snaps[0].amount):'')+' — undo?'),function(){undoRestoreTxns(snaps);});
  });
}
/* ================= batch select / edit / delete (v1.5) ================= */
function batchDel(){
  if(!BSEL.ids.length){toast('Tick at least one transaction first');return;}
  var snaps=DB.txns.filter(function(t){return BSEL.ids.indexOf(t.id)>=0;}).map(function(t){return Object.assign({},t);});
  var n=snaps.length;
  askConfirm('Delete '+n+' selected transaction'+(n>1?'s':'')+'? You can undo right after.','Delete '+n,function(){
    var ids={};snaps.forEach(function(s){ids[s.id]=1;});
    DB.txns=DB.txns.filter(function(t){return !ids[t.id];});
    BSEL.on=false;BSEL.ids=[];
    touch();
    toastAct('Deleted '+n+' — undo?',function(){undoRestoreTxns(snaps);});
  });
}
function batchField(key,label,ctrl){
  return '<div class="mgr-row"><label style="display:flex;align-items:center;gap:8px;flex:1;font-size:var(--fs-13);font-weight:700"><input type="checkbox" id="beUse_'+key+'" style="width:18px;height:18px;accent-color:var(--accent)">'+label+'</label></div>'
    +'<div style="padding:0 2px 10px">'+ctrl+'</div>';
}
function renderBatchEdit(){
  var n=BSEL.ids.length;
  if(!n){$('mgrBody').innerHTML='<div class="help" style="padding:8px 2px">No transactions selected — exit and tick some first.</div>';return;}
  var skip=0;
  BSEL.ids.forEach(function(id){var t=DB.txns.find(function(x){return x.id===id;});if(t&&t.type==='Transfer')skip++;});
  function opts(l){return l.map(function(c){return '<option value="'+esc(c)+'">'+esc(c)+'</option>';}).join('');}
  $('mgrBody').innerHTML=
    '<div class="help small" style="margin-bottom:10px">Tick a field, set its value, then apply — only ticked fields change. Applies to <b>'+n+'</b> selected transaction'+(n>1?'s':'')+'.'+(skip?(' '+skip+' transfer'+(skip>1?'s are':' is')+' skipped (transfers have no category/person).'):'')+'</div>'
    +batchField('cat','Category','<select class="fin" id="beCat"><option value="">— choose —</option><optgroup label="− Expense">'+opts(sortedAlpha(DB.categories.Expense||[]))+'</optgroup><optgroup label="＋ Income">'+opts(sortedAlpha(DB.categories.Income||[]))+'</optgroup></select>')
    +batchField('sub','Sub-category','<input class="fin" id="beSub" placeholder="leave blank to skip">')
    +batchField('acc','Account','<select class="fin" id="beAcc"><option value="">— choose —</option>'+opts(sortedAlpha(DB.accounts.map(function(a){return a.name;})))+'</select>')
    +batchField('per','Paid by (person)','<select class="fin" id="bePer"><option value="">— choose —</option>'+opts(sortedAlpha(DB.people))+'</select>')
    +batchField('note','Note (overwrite)','<input class="fin" id="beNote" placeholder="leave blank to skip">')
    +'<button class="btn" data-act="batchapply" style="width:100%;margin-top:4px">Apply to '+n+' transaction'+(n>1?'s':'')+'</button>';
}
function batchApply(){
  var use={};
  ['cat','sub','acc','per','note'].forEach(function(k){var c=$('beUse_'+k);if(c&&c.checked)use[k]=1;});
  if(!Object.keys(use).length){toast('Tick at least one field to apply');return;}
  if(!BSEL.ids.length){toast('No transactions selected');return;}
  var val={
    cat:($('beCat')||{}).value||'',
    sub:(($('beSub')||{}).value||'').trim(),
    acc:($('beAcc')||{}).value||'',
    per:($('bePer')||{}).value||'',
    note:(($('beNote')||{}).value||'').trim()
  };
  if(use.cat&&!val.cat){toast('Choose a category');return;}
  if(use.acc&&!val.acc){toast('Choose an account');return;}
  if(use.per&&!val.per){toast('Choose a person');return;}
  var snaps=[],applied=0,skip=0;
  BSEL.ids.forEach(function(id){
    var t=DB.txns.find(function(x){return x.id===id;});
    if(!t)return;
    if(t.type==='Transfer'||accLocked(t.account)){skip++;return;}
    snaps.push(Object.assign({},t));
    if(use.cat){t.category=val.cat;t.subcategory='';}
    if(use.sub){t.subcategory=val.sub;if(subList(t.category).indexOf(val.sub)<0)subList(t.category).push(val.sub);}
    if(use.acc)t.account=val.acc;
    if(use.per)t.person=val.per;
    if(use.note)t.note=val.note;
    applied++;
  });
  if(!applied){toast('Nothing changed (transfers skipped)');return;}
  closeMgr();
  BSEL.on=false;BSEL.ids=[];navSync(); /* v1.34: release the selection layer's spare history slot */
  touch();
  toastAct('Updated '+applied+(skip?' ('+skip+' skipped)':'')+' — undo?',function(){
    snaps.forEach(function(s){var t=DB.txns.find(function(x){return x.id===s.id;});if(t)Object.assign(t,s);});
    touch();toast('Reverted ✓');
  });
}

/* ================= navigation & actions ================= */
/* ===== v1.34: tab navigations join the history stack — the Android back button / browser
   Back now walks back through the screens you visited (and out of selection mode) instead
   of leaving the app. Feature-detected so the test sims (no history object) stay safe.
   Boot replaces the page's own entry with the root; every later view change pushes one
   entry; a tap that closes an open layer reuses that layer's spare slot via replaceState. */
var VIEWNAV={booted:false,restore:false,cur:''};
function histOK(){return typeof history!=='undefined'&&history&&typeof history.pushState==='function';}
function viewNav(v,spare){
  var first=!VIEWNAV.booted,same=(VIEWNAV.cur===v);
  VIEWNAV.booted=true;VIEWNAV.cur=v;
  if(VIEWNAV.restore){VIEWNAV.restore=false;return;} /* popstate restore — the entry already exists */
  if(same)return; /* same tab re-tapped — nothing to record */
  if(!histOK())return;
  try{
    if(first)history.replaceState({mmview:v,root:1},'');
    else if(spare){if(NAV._t){clearTimeout(NAV._t);NAV._t=null;}NAV.armed=false;history.replaceState({mmview:v},'');}
    else history.pushState({mmview:v},'');
  }catch(e){DIAG.note(e,"core/14-batch-select-edit-delete-v1-5:117");}
}
/* ===== v1.25: Back button / back gesture / Esc close the topmost open screen =====
   Layers bottom-up: tabs → report page → drill page → add/edit sheet (z61) → manager
   sheet (z73) → confirm & clear modals (z78). Every open/close funnel calls navSync(),
   which keeps ONE spare history entry armed while any layer is open: the phone Back
   button (popstate), the browser Back, or Esc then closes the topmost layer instead of
   leaving the app. */
var NAV={armed:false,echo:false};
function anyLayerOpen(){
  return $('cmodal').classList.contains('on')||$('clrmodal').classList.contains('on')||
    $('ovl').classList.contains('on')||$('mgrOvl').classList.contains('on')||
    DRILL.open||REPORT.open||BSEL.on; /* v1.34: batch selection is a Back-closable layer too */
}
function navClose(){ /* close ONE topmost layer; whatever is under it stays for the next Back */
  if($('cmodal').classList.contains('on')){confirmResolve(false);return;}
  if($('clrmodal').classList.contains('on')){$('clrmodal').classList.remove('on');navSync();return;}
  if($('mgrOvl').classList.contains('on')){closeMgr();return;}
  if($('ovl').classList.contains('on')){closeSheet();return;}
  if(BSEL.on){BSEL.on=false;BSEL.ids=[];renderTxns();navSync();return;} /* v1.34 */
  if(DRILL.open){drillBack();return;}
  if(REPORT.open)closeReport();
}
function navArm(){ /* arm a spare history entry so Back is intercepted while layers are open */
  if(NAV.armed)return;
  if(NAV._t){clearTimeout(NAV._t);NAV._t=null;NAV.armed=true;return;} /* a layer re-opened before the queued disarm-back ran — the spare entry was never popped, reuse it */
  try{history.pushState({mmnav:1},'');NAV.armed=true;}catch(e){DIAG.note(e,"core/14-batch-select-edit-delete-v1-5:143");}
}
function navSync(){
  if(anyLayerOpen()){navArm();return;}
  if(!NAV.armed)return;
  NAV.armed=false;
  /* defer the spare-entry pop by a tick: flows that close one layer and open another in the
     same task (clear-data → confirm, wizard steps) must not pop the entry the next layer arms */
  NAV._t=setTimeout(function(){
    NAV._t=null;NAV.echo=true; /* our own history.back() — popstate must ignore it */
    try{history.back();}catch(e){NAV.echo=false;}
  },0);
}
window.addEventListener('popstate',function(ev){
  if(NAV.echo){NAV.echo=false;return;} /* echo of our own history.back() after a UI close */
  if(NAV.armed){NAV.armed=false;navClose();return;}
  /* v1.34: no layer open — Back rewinds to the previously visited tab instead of exiting */
  var st=(ev&&typeof ev.state!=='undefined')?ev.state:null;
  if(st&&st.mmview&&st.mmview!==VIEWNAV.cur){VIEWNAV.restore=true;gotoView(st.mmview);}
  /* root / same view → nothing to restore; one more Back leaves the app as usual */
});
document.addEventListener('keydown',function(e){
  if(e.key!=='Escape'||!anyLayerOpen())return;
  e.preventDefault();navClose();
});
/* ===== beta 65: tab swipe + left-edge Back, rebuilt for touch (was v1.20/v1.22/v1.25/v1.36) =====
   Why: a swipe that started on any button, link, card row or the footer was ignored, so most of a
   screen was dead; chip strips that the old list did not name (report chips, account chips, tables)
   scrolled AND flipped the tab; and Settings / full-screen pages let the tab change underneath.
   Now: a swipe can start anywhere except text fields, sliders, the keypad, toasts, open sheets and
   things with their own drag (the payment banner). A strip that scrolls sideways keeps the swipe
   for itself unless it is already at its end, then the tab changes. The direction is locked after
   ~10 px so a scroll that drifts sideways never flips a tab, and a short quick flick is enough. */
var TAB_ORDER=['overview','txns','accounts','settings'],SWIPE=null,SWIPED_AT=0;
function swipeTabBlocked(){
  return $('ovl').classList.contains('on')||$('mgrOvl').classList.contains('on')||
    $('cmodal').classList.contains('on')||$('clrmodal').classList.contains('on')||
    DRILL.open||REPORT.open||!!document.querySelector('.page.on,.ov.on,#x63ov.on');
}
var SWIPE_OWN='input:not([type=button]):not([type=submit]):not([type=checkbox]):not([type=radio]),textarea,select,[contenteditable=""],[contenteditable=true],'+
  '.sheet,.cmodal,.toast,#toast,.swipe51,.banner51,#calcPad,.hrail,[data-noswipe]';
function swipeOwnTarget(t){return !!(t&&t.closest&&t.closest(SWIPE_OWN));}
/* nearest ancestor that really scrolls sideways (so far only the ones listed by class were known) */
function swipeHScroller(t){
  for(var n=t;n&&n.nodeType===1&&n!==document.body&&n!==document.documentElement;n=n.parentElement){
    if(n.scrollWidth>n.clientWidth+2){var ox=getComputedStyle(n).overflowX;if(ox==='auto'||ox==='scroll')return n;}
  }
  return null;
}
function swipeStart(e){
  if(e.touches.length!==1)return null;
  var t=e.target;if(swipeOwnTarget(t))return null;
  var sc=swipeHScroller(t);
  return {x:e.touches[0].clientX,y:e.touches[0].clientY,t:Date.now(),sy:window.scrollY,sc:sc,sl:sc?sc.scrollLeft:0,axis:''};
}
function swipeMove(st,e){
  if(!st||st.axis||e.touches.length!==1)return;
  var ax=Math.abs(e.touches[0].clientX-st.x),ay=Math.abs(e.touches[0].clientY-st.y);
  if(ax<10&&ay<10)return;
  st.axis=ax>ay*1.15?'x':'y'; /* locked once: a vertical scroll never turns into a tab flip */
}
/* returns dx when the finished touch was a clear sideways swipe, else 0 */
function swipeEnd(st,e,need){
  if(!st||st.axis==='y'||!e.changedTouches.length)return 0;
  var dx=e.changedTouches[0].clientX-st.x,dy=e.changedTouches[0].clientY-st.y,ax=Math.abs(dx),ay=Math.abs(dy);
  if(Math.abs(window.scrollY-st.sy)>12)return 0;               /* the page scrolled: it was a scroll */
  if(st.sc&&Math.abs(st.sc.scrollLeft-st.sl)>2)return 0;      /* a chip strip / chart scrolled instead */
  var dt=Date.now()-st.t;
  if(ax<(dt<300?need[0]:need[1])||ax<ay*1.3)return 0;
  return dx;
}
document.addEventListener('touchstart',function(e){
  SWIPE=null;
  if(swipeTabBlocked())return;
  SWIPE=swipeStart(e);
},{passive:true});
document.addEventListener('touchmove',function(e){swipeMove(SWIPE,e);},{passive:true});
document.addEventListener('touchend',function(e){
  var st=SWIPE;SWIPE=null;
  if(!st||swipeTabBlocked())return;
  var dx=swipeEnd(st,e,[32,56]);if(!dx)return;
  var cur=document.querySelector('.nbtn.on');
  if(!cur)return;
  var nxt=TAB_ORDER[TAB_ORDER.indexOf(cur.dataset.v)+(dx<0?1:-1)];
  if(nxt){SWIPED_AT=Date.now();gotoView(nxt);} /* swipe left → next tab, swipe right → previous tab */
},{passive:true});
document.addEventListener('touchcancel',function(){SWIPE=null;EDGEBACK=null;},{passive:true});
/* a swipe that began on a button must not also press it */
window.addEventListener('click',function(e){if(Date.now()-SWIPED_AT<400){e.preventDefault();e.stopPropagation();}},true);
/* ===== left-edge swipe = Back on drill / report / Settings and other full-screen pages ===== */
var EDGEBACK=null;
function edgeBackOn(){return DRILL.open||REPORT.open||!!document.querySelector('.page.on');}
document.addEventListener('touchstart',function(e){
  EDGEBACK=null;
  if(e.touches.length!==1||!edgeBackOn())return;
  if(e.touches[0].clientX>72)return; /* the gesture must start in the left edge strip */
  if($('cmodal').classList.contains('on')||$('clrmodal').classList.contains('on')||$('ovl').classList.contains('on')||$('mgrOvl').classList.contains('on'))return;
  EDGEBACK=swipeStart(e);
},{passive:true});
document.addEventListener('touchmove',function(e){swipeMove(EDGEBACK,e);},{passive:true});
document.addEventListener('touchend',function(e){
  var st=EDGEBACK;EDGEBACK=null;
  if(!st||!edgeBackOn())return;
  var dx=swipeEnd(st,e,[40,56]);
  if(dx<=0)return; /* a firm rightward swipe, not a scroll */
  SWIPED_AT=Date.now();
  if(DRILL.open)drillBack();else if(REPORT.open)closeReport();else navClose();
},{passive:true});
