/* ===================== v1.36: couple reports — week / month period engine ===================== */
var PER={mode:'month',off:0};
function perTitle21(fb){try{if(PER.off===0)return PER.mode==='week'?'This week':PER.mode==='year'?'This year':'This month';}catch(e){DIAG.note(e,"core/16-v1-36-couple-reports-week-month:3");}return fb;}
function isoD(d){return d.getFullYear()+'-'+pad2(d.getMonth()+1)+'-'+pad2(d.getDate());}

function expBy(list,kf){var m={};list.forEach(function(t){if(t.type!=='Expense')return;var k=kf(t);m[k]=(m[k]||0)+t.amount;});return m;}
function sumT(list,ty){return list.reduce(function(a,t){return a+(t.type===ty?t.amount:0);},0);}

function pctChg(a,b){if(!b)return a?'new':'—';var p=Math.round((a-b)/Math.abs(b)*100);return (p>0?'▲ ':p<0?'▼ ':'')+Math.abs(p)+'%';}
function kpi(l,v,c){return '<div class="kpi"><small>'+l+'</small><b class="'+(c||'')+'">'+v+'</b></div>';}
function sdot(c){return '<span class="lg-dot" style="background:'+c+'"></span>';}

function budgetBar(a,b){
  var p=b>0?Math.min(100,a/b*100):0,col=a>b?'var(--exp)':(p>85?'var(--warn)':'var(--inc)');
  return '<div class="bbar"><i style="width:'+p.toFixed(1)+'%;background:'+col+'"></i></div><div class="help small" style="margin-top:4px">'+Math.round(b>0?a/b*100:0)+'% of the '+money(b)+' '+perWord()+'ly budget used</div>';
}

/* 1 — Couple snapshot */

/* 2 — Between Us (uses the “X owes Y” debt ledgers) */
function ledgers(){
  var bm={};balances().rows.forEach(function(r){bm[r.name]=r.bal;});
  var nm=[];DB.accounts.forEach(function(a){if(/^.+ owes .+$/.test(a.name))nm.push(a.name);});
  Object.keys(bm).forEach(function(n){if(/^.+ owes .+$/.test(n)&&nm.indexOf(n)<0)nm.push(n);});
  return nm.map(function(n){return {name:n};}).map(function(a){
    var pp=a.name.split(' owes '),b=Math.round((bm[a.name]||0)*100)/100;
    return {name:a.name,bal:b,debtor:b>=0?pp[0]:pp[1],creditor:b>=0?pp[1]:pp[0],amt:Math.abs(b)};
  });
}

/* v1.41: settle a credit-card / debt — a Transfer from the account owner's cash/bank account into the card */
function openCardPay(n,amt){
  var card=DB.accounts.find(function(a){return a.name===n;});if(!card)return;
  var src=DB.accounts.filter(function(a){return a.name!==n&&accTypeKind(a.type)!=='liability'&&!isRecvAcc(a.name);});
  var pick=src.find(function(a){return card.owner&&a.owner===card.owner;})||src[0];
  if(!pick){toast('Add a bank or cash account to pay from first');return;}
  openSheet();setFormType('Transfer');
  $('fAccount').innerHTML=accOptions(pick.name);$('fTo').innerHTML=accOptions(n);
  $('fAmount').value=amt;$('fNote').value='Card payment';
  $('sheetTitle').textContent='Pay '+n;
  updateOwnerUI();
}
function openSettle(n){
  var l=ledgers().find(function(x){return x.name===n;});if(!l)return;
  var acc=DB.accounts.filter(function(a){return !isRecvAcc(a.name);});
  function accOf(p){var a=acc.find(function(x){return x.owner===p;});return a?a.name:(acc[0]?acc[0].name:'');}
  if(!DB.accounts.some(function(a){return a.name===n;}))ensureRecvAcc(n);
  openSheet();setFormType('Transfer');
  if(l.bal>0){$('fAccount').innerHTML=accOptions(n);$('fTo').innerHTML=accOptions(accOf(l.creditor));}
  else{$('fAccount').innerHTML=accOptions(accOf(l.debtor));$('fTo').innerHTML=accOptions(n);}
  $('fAmount').value=l.amt;$('fNote').value='Settle up';
  $('sheetTitle').textContent='Settle up: '+l.debtor+' → '+l.creditor;
  updateOwnerUI();
}
