/* 5 — Shared vs personal */
function repShared(){
  var r=perRange(),L=perTx(r),sh={},pe={},inc={},tE=0,tI=0;
  L.forEach(function(t){var p=t.person||'No account owner';
    if(t.type==='Expense'){if(t.group)sh[p]=(sh[p]||0)+t.amount;else pe[p]=(pe[p]||0)+t.amount;tE+=t.amount;}
    else if(t.type==='Income'){inc[p]=(inc[p]||0)+t.amount;tI+=t.amount;}});
  var ppl=peopleWith(Object.assign({},sh,pe,inc));
  function line(lb,f,cls){return '<tr><td>'+lb+'</td>'+ppl.map(function(p){return '<td class="r '+(cls||'')+'">'+f(p)+'</td>';}).join('')+'</tr>';}
  var notes=ppl.map(function(p){var se=tE?((sh[p]||0)+(pe[p]||0))/tE:0,si=tI?(inc[p]||0)/tI:0;if(!tE||!tI)return '';var d=Math.round((se-si)*100);return Math.abs(d)>=10?'<li><b>'+esc(p)+'</b> pays '+Math.abs(d)+' points '+(d>0?'more':'less')+' of the spending than their share of income.</li>':'';}).join('');
  return '<div class="card"><h2>'+ico('users')+' Shared vs personal <span class="sub">'+esc(r.label)+'</span></h2>'
    +'<div style="overflow-x:auto"><table class="rtab"><thead><tr><th></th>'+ppl.map(function(p){return '<th class="r">'+esc(p)+'</th>';}).join('')+'</tr></thead><tbody>'
    +line('Shared (split bills)',function(p){return money(sh[p]||0);})
    +line('Personal',function(p){return money(pe[p]||0);})
    +line('<b>Total spent</b>',function(p){return '<b>'+money((sh[p]||0)+(pe[p]||0))+'</b>';})
    +line('Share of spending',function(p){return tE?Math.round(((sh[p]||0)+(pe[p]||0))/tE*100)+'%':'—';})
    +line('Share of income',function(p){return tI?Math.round((inc[p]||0)/tI*100)+'%':'—';})
    +'</tbody></table></div>'
    +(notes?'<ul class="help small" style="padding-left:18px;margin-top:6px">'+notes+'</ul>':'')+'</div>';
}
/* 6 — Cash flow & savings rate */

/* 7 — Fixed vs variable */

function repFixed(){
  var r=perRange(),L=perTx(r).filter(function(t){return t.type==='Expense';}),fx=0,va=0,fm={},vm={};
  L.forEach(function(t){if(isFixed(t)){fx+=t.amount;fm[t.category]=(fm[t.category]||0)+t.amount;}else{va+=t.amount;vm[t.category]=(vm[t.category]||0)+t.amount;}});
  var tot=fx+va;
  function lst(m){var ks=Object.keys(m).sort(function(a,b){return m[b]-m[a];});return ks.length?ks.slice(0,8).map(function(c){return '<div class="fline"><span>'+esc(c)+'</span><b>'+money(m[c])+'</b></div>';}).join(''):'<div class="help small" style="padding:6px 2px">None</div>';}
  return '<div class="card"><h2>'+ico('repeat')+' Fixed vs variable <span class="sub">'+esc(r.label)+'</span></h2>'
    +'<div class="kpis">'+kpi('Fixed',money(fx)+(tot?' · '+Math.round(fx/tot*100)+'%':''),'')+kpi('Variable',money(va)+(tot?' · '+Math.round(va/tot*100)+'%':''),'neg')+'</div>'
    +(tot?'<div class="bbar"><i style="width:'+(fx/tot*100).toFixed(1)+'%;background:var(--accent)"></i></div>':'')
    +'<div class="mgr-sec">Fixed costs</div>'+lst(fm)+'<div class="mgr-sec">Variable, where you can cut back</div>'+lst(vm)
    +'<div class="help small" style="margin-top:8px">Fixed = recurring transactions and any category ticked “Fixed” in Settings → Budgets &amp; fixed costs.</div></div>';
}
