/* 9 — Top merchants & subscription audit */
function recurMonthly(r){var e=r.every||1,a=Math.abs(+r.tpl.amount||0);return r.freq==='month'?a/e:r.freq==='week'?a*52/12/e:r.freq==='day'?a*365/12/e:a/12/e;}
function repMerch(){
  var r=perRange(),m={};
  perTx(r).forEach(function(t){if(t.type!=='Expense')return;var lb=String(t.note||t.subcategory||t.category||'—').trim(),k=lb.toLowerCase();if(!m[k])m[k]={lb:lb,v:0,n:0};m[k].v+=t.amount;m[k].n++;});
  var top=Object.keys(m).map(function(k){return m[k];}).sort(function(a,b){return b.v-a.v;}).slice(0,10);
  var subs=DB.recur.filter(function(x){return x.tpl&&x.tpl.type==='Expense';}).map(function(x){return {lb:x.tpl.note||x.tpl.subcategory||x.tpl.category,cat:x.tpl.category,who:x.tpl.person,m:recurMonthly(x),next:x.next};}).sort(function(a,b){return b.m-a.m;});
  var sm=subs.reduce(function(a,x){return a+x.m;},0);
  return '<div class="card"><h2>'+ico('bag')+' Top merchants <span class="sub">'+esc(r.label)+' · by note, else sub-category</span></h2><div class="rows">'
    +(top.length?top.map(function(x,i){return trow({rank:'#'+(i+1),lb:esc(x.lb),sub:x.n+' purchase'+(x.n===1?'':'s'),amt:money(x.v),cls:'neg'});}).join(''):'<div class="help" style="padding:8px 2px">No spending in this period.</div>')+'</div></div>'
    +'<div class="card"><h2>'+ico('repeat')+' Subscriptions &amp; recurring <span class="sub">'+money(sm)+' / month · '+money(sm*12)+' / year</span></h2><div class="rows">'
    +(subs.length?subs.map(function(x){return trow({lb:esc(x.lb||'—'),sub:esc(x.cat||'')+' · '+esc(x.who||'—')+(x.next?' · next '+dLabel(x.next):''),amt:money(x.m)+'<span class="muted small"> /mo</span>'});}).join(''):'<div class="help" style="padding:8px 2px">No recurring expenses. Set Repeat on a transaction to track subscriptions.</div>')+'</div>'
    +'<div class="help small" style="margin-top:8px">Check this list now and then for subscriptions you no longer use.</div></div>';
}
