/* ---------- 1. who owes whom: balances as at the end of the chosen period ---------- */
function ledgersAt(d){
  return ledgers().map(function(l){
    var b=Math.round(accountBalAsOf(l.name,d)*100)/100,pp=l.name.split(' owes ');
    return {name:l.name,bal:b,debtor:b>=0?pp[0]:pp[1],creditor:b>=0?pp[1]:pp[0],amt:Math.abs(b)};
  });
}
function oweTxt(name,b){var pp=name.split(' owes ');if(Math.abs(b)<0.005)return 'All settled';return (b>0?esc(pp[0])+' owes '+esc(pp[1]):esc(pp[1])+' owes '+esc(pp[0]))+' '+money(Math.abs(b));}
function repSettle48(){
  var r=perRange(),td=todayISO(),asd=r.e<td?r.e:td,isNow=asd===td,before=addDaysISO(r.s,-1);
  var ls=ledgersAt(asd);
  if(whoOK()!=='couple')ls=ls.filter(function(l){return l.name.split(' owes ').indexOf(PER.who)>=0;});
  var hd='<h2>'+ico('scale')+' Between Us <span class="sub">as at '+dLabelYW(asd)+'</span></h2>';
  if(!ls.length)return '<div class="card">'+hd+'<div class="help">No shared debts'+(PER.who==='couple'?'':' for '+esc(PER.who))+'. Split a bill between two people, or tick “Amount owed” on a transfer, and it will show up here.</div></div>';
  return ls.map(function(l){
    var o=Math.round(accountBalAsOf(l.name,before)*100)/100,add=0,red=0,n=0;
    DB.txns.forEach(function(t){if(t.date<r.s||t.date>asd||!txnTouchesAcc(t,l.name))return;var v=accEffect(t,l.name);if(v>=0)add+=v;else red-=v;n++;});
    var done=l.amt<0.005;
    return '<div class="card">'+hd+'<div class="rows">'
      +'<div class="fline"><span>At the start · '+dLabelY(before)+'</span><b>'+oweTxt(l.name,o)+'</b></div>'
      +'<div class="fline"><span>Added in '+esc(r.label)+'<br><small class="muted">split shares, loans</small></span><b>+ '+money(add)+'</b></div>'
      +'<div class="fline"><span>Reduced in '+esc(r.label)+'<br><small class="muted">repayments, refunds, income shares</small></span><b>− '+money(red)+'</b></div>'
      +'<div class="fline eq"><span>As at '+dLabelY(asd)+(n?' <small class="muted">· '+n+' transaction'+(n===1?'':'s')+'</small>':'')+'</span><b class="'+(done?'pos':'neg')+'">'+oweTxt(l.name,l.bal)+'</b></div></div>'
      +(isNow&&!done?'<button class="btn" style="margin-top:10px" data-act="settle" data-n="'+esc(l.name)+'">'+ico('check')+' Settle up '+money(l.amt)+'</button>':'')
      +(!isNow?'<div class="help small" style="margin-top:8px">Today: '+oweTxt(l.name,Math.round(accountBalAsOf(l.name,td)*100)/100)+'</div>':'')+'</div>';
  }).join('');
}
DYNF.settle=repSettle48;
/* ---------- 3. calculator: every amount field accepts sums and opens a calculator keypad ---------- */
function calcEval(s){
  s=String(s==null?'':s).replace(/[,\s]/g,'').replace(/×/g,'*').replace(/÷/g,'/').replace(/[−–]/g,'-').replace(/[+\-*/]+$/,'');
  if(!s||!/^[0-9.+\-*/()]+$/.test(s))return NaN;
  var i=0;
  function num(){var m=s.slice(i).match(/^\d*\.?\d+|^\d+\.?/);if(!m)throw 0;i+=m[0].length;return parseFloat(m[0]);}
  function fac(){var c=s.charAt(i);if(c==='-'){i++;return -fac();}if(c==='+'){i++;return fac();}if(c==='('){i++;var v=expr();if(s.charAt(i)!==')')throw 0;i++;return v;}return num();}
  function term(){var v=fac();while(s.charAt(i)==='*'||s.charAt(i)==='/'){var o=s.charAt(i++),w=fac();v=o==='*'?v*w:v/w;}return v;}
  function expr(){var v=term();while(s.charAt(i)==='+'||s.charAt(i)==='-'){var o=s.charAt(i++),w=term();v=o==='+'?v+w:v-w;}return v;}
  try{var r=expr();return i===s.length&&isFinite(r)?r:NaN;}catch(e){return NaN;}
}
function calcHasOp(s){s=String(s||'').replace(/[\s,]/g,'');return /[+*/×÷]/.test(s)||/[0-9.)]-/.test(s);}
var _parseAmt48=parseAmt;
parseAmt=function(v){
  if(typeof v==='string'&&calcHasOp(v)){var s=v.replace(/[^0-9.+\-*/()×÷−]/g,'');var r=calcEval(s);if(isFinite(r))return Math.round(r*100)/100;}
  return _parseAmt48(v);
};
var CALC={el:null,open:false,fresh:false};
var CALC_SEL='#fAmount,#fSplitRows input[data-sf="v"],#mgrEStart,#mgrNewStart,.bgrow input.fin,#gaT,#geT,#gcAmt';
function calcMark(){var l=document.querySelectorAll(CALC_SEL),i;for(i=0;i<l.length;i++)if(l[i].getAttribute('inputmode')!=='none'){l[i].setAttribute('inputmode','none');l[i].setAttribute('autocomplete','off');}}
function calcFire(el){try{el.dispatchEvent(new Event('input',{bubbles:true}));}catch(e){DIAG.note(e,"core/18-v1-48-who-owes-whom-as-at-period:52");}}
function calcPrev(){var el=CALC.el,b=$('cpRes');if(!el||!b)return;var v=el.value,r=calcEval(v);b.textContent=calcHasOp(v)?('= '+(isFinite(r)?fmt(r):'…')):(v?fmt(parseAmt(v)):'');}
function calcLabel(el){if(el.id==='fAmount')return 'Amount';if(el.dataset.sf==='v')return 'Split share';var a=el.getAttribute('aria-label');if(a)return a.charAt(0).toUpperCase()+a.slice(1);if(el.id==='gcAmt')return 'Goal amount';if(/T$/.test(el.id))return 'Goal target';return 'Start balance';}
function calcOpen(el){
  CALC.el=el;CALC.open=true;CALC.fresh=true;
  $('cpLbl').innerHTML=ico('calc')+' '+esc(calcLabel(el));
  $('calcPad').classList.add('on');document.body.classList.add('calc-on');calcPrev();
  setTimeout(function(){try{el.scrollIntoView({block:'center',behavior:'smooth'});}catch(e){DIAG.note(e,"core/18-v1-48-who-owes-whom-as-at-period:59");}},80);
  navSync();
}
function calcSettle(el){if(el&&calcHasOp(el.value)){var r=calcEval(el.value);if(isFinite(r)){el.value=String(Math.round(r*100)/100);calcFire(el);}}}
function calcClose(ev){
  var el=CALC.el;if(ev!==false)calcSettle(el);
  CALC.el=null;CALC.open=false;$('calcPad').classList.remove('on');document.body.classList.remove('calc-on');
  if(el&&document.activeElement===el)el.blur();
  navSync();
}
function calcKey(k){
  var el=CALC.el;if(!el)return;var v=el.value||'';
  if(k==='done'){calcClose(true);return;}
  if(k==='='){calcSettle(el);CALC.fresh=true;calcPrev();return;}
  if(k==='C')v='';
  else if(k==='bk')v=v.slice(0,-1);
  else if('+-*/'.indexOf(k)>=0){if(v===''&&k!=='-')return;v=/[+\-*/]$/.test(v)?v.slice(0,-1)+k:v+k;}
  else{if(CALC.fresh)v='';if(k==='.'){var seg=v.split(/[+\-*/]/).pop();if(seg.indexOf('.')>=0)return;if(seg==='')v+='0';}v+=k;}
  CALC.fresh=false;el.value=v;calcFire(el);calcPrev();
}
document.addEventListener('focusin',function(e){if(isCalcEl(e.target)){if(CALC.el&&CALC.el!==e.target)calcSettle(CALC.el);calcOpen(e.target);}});
document.addEventListener('focusout',function(e){
  if(!CALC.open||e.target!==CALC.el)return;
  var rt=e.relatedTarget;if(rt&&$('calcPad').contains(rt))return;
  setTimeout(function(){if(!CALC.open)return;var a=document.activeElement;if(a&&(isCalcEl(a)||$('calcPad').contains(a)))return;calcClose(true);},150);
});
document.addEventListener('keydown',function(e){if(e.key==='Enter'&&isCalcEl(e.target)){calcSettle(e.target);calcPrev();}});
/* ---------- 4/5. split bill: edit / delete this share or the whole bill ---------- */
var CH={opts:[]};
