function fbSignIn(kind){
  var ms=kind==='ms',nm=ms?'Microsoft':'Google';
  if(!fbLooksBrowser()){toast('Sign-in needs a browser with internet');return;}
  if(!fbOnSite()){toast(nm+' sign-in works when the app is opened from its website.');return;}
  toast('Opening '+nm+' sign-in…');
  fbLoad().then(function(){
    if(ms)return dynImport('https://www.gstatic.com/firebasejs/'+FBJS+'/firebase-auth.js').then(function(A){var p=new A.OAuthProvider('microsoft.com');p.setCustomParameters({prompt:'select_account'});p.addScope('email');return p;});
    if(!FB.provider)FB.provider=new FB.mod.GoogleAuthProvider();
    return FB.provider;
  }).then(function(prov){
    if(fbIOSStandalone()){FB.mod.signInWithRedirect(FB.auth,prov);return;}
    return FB.mod.signInWithPopup(FB.auth,prov).catch(function(e){var c=(e&&e.code)||'';if(c==='auth/popup-blocked'||c==='auth/operation-not-supported-in-this-environment'||c==='auth/cancelled-popup-request')return FB.mod.signInWithRedirect(FB.auth,prov);throw e;});
  }).catch(function(e){
    var c=(e&&e.code)||'';
    if(c==='auth/popup-closed-by-user')return;
    if(c==='auth/unauthorized-domain'){toast(nm+' sign-in isn\'t set up for this site yet. Your data is still on this device.');return;}
    if(c==='auth/operation-not-allowed'){toast(nm+' sign-in is not switched on in Firebase yet.');return;}
    if(c==='auth/account-exists-with-different-credential'){toast('This email already signs in another way. Use that button instead.');return;}
    toast('Sign-in failed. Check your connection and try again.');
  });
};
