function stmCatFn(){
  var hist={};
  DB.txns.forEach(function(t){if(t.type==='Transfer'||!t.note||t.masked)return;var k=t.type+'|'+String(t.note).toLowerCase().trim();(hist[k]=hist[k]||{})[t.category]=((hist[k]||{})[t.category]||0)+1;});
  return function(desc,type){
    var cats=DB.categories[type]||[],ld=String(desc||'').toLowerCase(),best='',bn=0;
    var h=hist[type+'|'+ld.trim()];if(h)Object.keys(h).forEach(function(c){if(h[c]>bn&&cats.indexOf(c)>=0){bn=h[c];best=c;}});
    if(best)return best;
    Object.keys(hist).forEach(function(k){var p=k.split('|');if(p[0]!==type||p[1].length<4||ld.indexOf(p[1])<0)return;Object.keys(hist[k]).forEach(function(c){if(hist[k][c]>bn&&cats.indexOf(c)>=0){bn=hist[k][c];best=c;}});});
    if(best)return best;
    for(var i=0;i<STM_RULES.length;i++)if(STM_RULES[i][0].test(desc)&&cats.indexOf(STM_RULES[i][1])>=0)return STM_RULES[i][1];
    return cats.indexOf('Others')>=0?'Others':(cats[0]||'Others');
  };
}
