function monthRowsHTML(tl,acc,rb){
  var seen={},rows=[];
  tl.slice().reverse().forEach(function(t){
    if(t.group){if(seen[t.group])return;var legs=tl.filter(function(x){return x.group===t.group&&x.date===t.date;});
      if(legs.length>1){seen[t.group]=1;var lb;legs.forEach(function(x){if(rb.tx[x.id]!==undefined)lb=rb.tx[x.id];});rows.push(cycGrpRow(t.group,legs,acc,lb).replace('</small></span>',' · '+dLabelW(t.date)+'</small></span>'));return;}}
    rows.push(accTxnRow(t,acc,rb.tx[t.id]));
  });
  return rows.join('');
}

