calcMark=function(){
  var l=document.querySelectorAll(CALC_SEL),i;
  for(i=0;i<l.length;i++){
    var el=l[i];
    if(el!==CALC.want&&el.getAttribute('inputmode')==='none')el.setAttribute('inputmode','decimal');
    if(el.dataset.cw)continue;el.dataset.cw='1';
    var b=document.createElement('button');b.type='button';b.className='calcbtn';b.setAttribute('data-act','calcbtn');b.setAttribute('aria-label','Open calculator');b.tabIndex=-1;b.innerHTML=ico('calc');
    if(el.id==='fAmount'){b.classList.add('in-amt');el.parentNode.appendChild(b);continue;}
    var w=document.createElement('span');w.className='calcw';
    if(el.style.marginBottom){w.style.marginBottom=el.style.marginBottom;el.style.marginBottom='0';}
    el.parentNode.insertBefore(w,el);w.appendChild(el);w.appendChild(b);
  }
};
var _cc50=calcClose;calcClose=function(ev){var el=CALC.el;_cc50(ev);if(el)el.setAttribute('inputmode','decimal');CALC.want=null;};
function calcFromBtn(btn){
  var inp=btn.parentNode&&btn.parentNode.querySelector('input.fin');if(!inp)return;
  if(CALC.open&&CALC.el===inp){calcClose(true);return;}
  if(CALC.open)calcClose(true);
  CALC.want=inp;inp.setAttribute('inputmode','none');
  if(document.activeElement===inp){inp.blur();setTimeout(function(){inp.focus();},40);}else inp.focus();
  setTimeout(function(){if(CALC.want===inp&&!CALC.open)calcOpen(inp);},120);
}

