/* ---------- 3. email account (compulsory) + first person ---------- */
var AU={mode:'signup',busy:false,err:''};
function acctMap(){try{return JSON.parse(localStorage.getItem('mm_accts')||'{}')||{};}catch(e){return {};}}
function acctSaveMap(m){try{localStorage.setItem('mm_accts',JSON.stringify(m));}catch(e){DIAG.note(e,"core/21-v1-51-couple-money-manager-email:20");}}
function sessGet(){try{return JSON.parse(localStorage.getItem('mm_sess')||'null');}catch(e){return null;}}
function sessSet(s){try{if(s)localStorage.setItem('mm_sess',JSON.stringify(s));else localStorage.removeItem('mm_sess');}catch(e){DIAG.note(e,"core/21-v1-51-couple-money-manager-email:22");}}
function emailOK(e){return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(e);}
function pwHash(salt,pw){
  var txt='cmm|'+salt+'|'+pw;
  try{if(window.crypto&&crypto.subtle&&window.TextEncoder){return crypto.subtle.digest('SHA-256',new TextEncoder().encode(txt)).then(function(b){return Array.prototype.map.call(new Uint8Array(b),function(x){return ('0'+x.toString(16)).slice(-2);}).join('');});}}catch(e){DIAG.note(e,"core/21-v1-51-couple-money-manager-email:26");}
  var h1=5381,h2=52711,i;for(i=0;i<txt.length;i++){var c=txt.charCodeAt(i);h1=((h1<<5)+h1+c)|0;h2=((h2<<5)+h2^c)|0;}return Promise.resolve('f'+(h1>>>0).toString(16)+(h2>>>0).toString(16));
}
function cloudAuth(kind,email,pw){
  if(!(fbOnSite()&&fbLooksBrowser()&&navigator.onLine!==false))return Promise.resolve({ok:false,why:'offline'});
  var p=fbLoad().then(function(){return dynImport('https://www.gstatic.com/firebasejs/'+FBJS+'/firebase-auth.js');}).then(function(A){
    if(kind==='reset')return A.sendPasswordResetEmail(FB.auth,email).then(function(){return {ok:true};});
    if(kind==='up')return A.createUserWithEmailAndPassword(FB.auth,email,pw).catch(function(e){if(e&&e.code==='auth/email-already-in-use')return A.signInWithEmailAndPassword(FB.auth,email,pw);throw e;}).then(function(){return {ok:true};});
    return A.signInWithEmailAndPassword(FB.auth,email,pw).then(function(){return {ok:true};});
  }).catch(function(e){return {ok:false,why:(e&&e.code)||'error'};});
  var t=new Promise(function(res){setTimeout(function(){res({ok:false,why:'timeout'});},12000);});
  return Promise.race([p,t]);
}
function authShow(mode){AU.mode=mode||AU.mode;AU.err='';$('authScr').hidden=false;document.body.classList.add('authon');renderAuth();}
function authHide(){$('authScr').hidden=true;document.body.classList.remove('authon');}
function auSubmit(){
  if(AU.busy)return;
  var m=AU.mode,em=(($('auEmail')||{}).value||'').trim().toLowerCase(),pw=($('auPw')||{}).value||'',pw2=($('auPw2')||{}).value||'';
  AU.err='';
  if(!emailOK(em)){AU.err='Enter a valid email address.';renderAuth();$('auEmail').value=em;return;}
  if(pw.length<6){AU.err='Password must be at least 6 characters.';renderAuth();$('auEmail').value=em;return;}
  if(m==='signup'&&pw!==pw2){AU.err='The passwords do not match.';renderAuth();$('auEmail').value=em;return;}
  var map=acctMap(),rec=map[em];
  AU.busy=true;renderAuth();$('auEmail').value=em;
  function done(mode){AU.busy=false;sessSet({email:em,mode:mode,at:Date.now()});DB.meta.acctEmail=em;save();if(!(DB.meta.profile&&DB.meta.profile.name&&DB.people.indexOf(DB.meta.profile.name)>=0)){AU.mode='person';renderAuth();}else{authHide();afterLogin();}}
  function fail(msg){AU.busy=false;AU.err=msg;renderAuth();$('auEmail').value=em;}
  if(m==='signup'){
    if(rec){fail('This email already has an account on this phone. Log in instead.');return;}
    var salt=uid();
    pwHash(salt,pw).then(function(h){
      return cloudAuth('up',em,pw).then(function(r){
        map[em]={salt:salt,hash:h,mode:r.ok?'cloud':'local',created:Date.now()};acctSaveMap(map);
        if(!r.ok&&r.why==='auth/weak-password'){toast('Cloud sign-in needs a stronger password. Saved on this device only.');}
        else if(!r.ok&&r.why!=='offline'&&r.why!=='timeout')toast('Account saved on this phone. Cloud sign-in is not available yet.');
        done(r.ok?'cloud':'local');
      });
    }).catch(function(){fail('Something went wrong. Try again.');});
    return;
  }
  if(rec){
    pwHash(rec.salt,pw).then(function(h){
      if(h!==rec.hash){fail('Wrong email or password.');return;}
      done(rec.mode);
      if(rec.mode==='cloud')cloudAuth('in',em,pw);
    });
    return;
  }
  cloudAuth('in',em,pw).then(function(r){
    if(!r.ok){fail(r.why==='offline'?'No account with this email on this phone. Create one, or open the app from its website to log in to the cloud.':'Wrong email or password.');return;}
    var salt=uid();pwHash(salt,pw).then(function(h){map[em]={salt:salt,hash:h,mode:'cloud',created:Date.now()};acctSaveMap(map);done('cloud');});
  });
}
function auForgot(){
  var em=(($('auEmail')||{}).value||'').trim().toLowerCase(),rec=acctMap()[em];
  function keepEmail(){var e=$('auEmail');if(e)e.value=em;}
  function localReset(){
    askConfirm('Reset the login for '+em+' on this phone? Your money data is kept. You can then create the profile again with a new password.','Reset login',function(){
      var m=acctMap();delete m[em];acctSaveMap(m);AU.mode='signup';AU.err='';renderAuth();keepEmail();toast('Login reset. Create your profile again.');
    });
  }
  if(!emailOK(em)){AU.err='Type your email first.';renderAuth();keepEmail();return;}
  if(rec&&rec.mode==='local'){localReset();return;}
  AU.err='';
  cloudAuth('reset',em).then(function(r){
    if(r&&r.ok){toast('Password reset email sent to '+em);return;}
    var c=(r&&r.why)||'';
    AU.err=c==='offline'||c==='timeout'
      ?'Connect to the internet and open the app from its website to reset this cloud password.'
      :c==='auth/operation-not-allowed'
        ?'Password recovery is not enabled for this cloud account yet.'
        :'We could not send the password reset email. Check the address and try again.';
    renderAuth();keepEmail();
  }).catch(function(){AU.err='We could not send the password reset email. Check your connection and try again.';renderAuth();keepEmail();});
}

