    if(res.needMap){openMgr('stmmap');toast('Tell the app which column is which. This is only needed once per bank.');return;}
    if(!res.text&&res.grid)res.text=res.grid.slice(0,40).map(function(R){return (R||[]).join(' ');}).join('\n');
    stmReview(res,f);
