function stmClassify(all){
  var cf=stmCatFn(),liab=stmIsLiab();
  STM.rows.forEach(function(r){
    if(r.touched&&!all)return;
    var d=r.desc;r.kind=r.type==='Income'?'in':'out';r.other='';
    if(r.type==='Income'&&/refund|reversal|rebate|cashback|refunded/i.test(d))r.kind='refund';
    if(liab&&r.type==='Income'&&/payment|bayaran|thank you|pymt|pmt|received/i.test(d)){var o=stmPickOther(false);if(o){r.kind='trf';r.dir='in';r.other=o;}}
    else if(!liab&&r.type==='Expense'&&/card|credit|visa|master|amex|kad kredit|cc pay/i.test(d)&&TRF_RE.test(d)){var o2=stmPickOther(true);if(o2){r.kind='trf';r.dir='out';r.other=o2;}}
    var ty=r.kind==='in'?'Income':'Expense';
    r.cat=cf(d,ty);r.auto=STX.lastAuto;r.cat0=r.cat;
    if(r.kind==='trf'){r.cat='';r.auto='';}
  });
}
function dDiff(a,b){return Math.round(Math.abs(Date.parse(a)-Date.parse(b))/864e5);}
function toks(s){return String(s||'').toLowerCase().split(/[^a-z0-9]+/).filter(function(x){return x.length>=3;});}
function simil(a,b){var A=toks(a),B=toks(b);if(!A.length||!B.length)return 0;var n=0;A.forEach(function(x){if(B.indexOf(x)>=0)n++;});return n/Math.min(A.length,B.length);}
function stmDup2(first){
  var acc=STM.acc;
  STM.rows.forEach(function(r){
    var amt=Math.abs(parseAmt(r.amount)),best=null,bs=-1;
    DB.txns.forEach(function(t){
      if(t.masked||Math.abs(Math.abs(t.amount)-amt)>0.005)return;
      var dd=dDiff(t.date,r.date);if(dd>2)return;
      var touches=t.account===acc||t.to===acc,other=r.kind==='trf'&&r.other&&(t.account===r.other||t.to===r.other);
      if(!touches&&!other)return;
      var sc=simil(r.desc,(t.note||'')+' '+(t.category||'')+' '+(t.subcategory||''));
      if(dd===0||sc>=0.3){var score=(3-dd)+sc*3+(touches?1:0);if(score>bs){bs=score;best=t;}}
    });
    var was=!!r.match;r.match=best;
    if(best&&!was&&(first||!r.touched))r.inc=false;
  });
}
function stmEffect(r){var a=Math.abs(parseAmt(r.amount))||0;if(r.kind==='in'||r.kind==='refund')return a;if(r.kind==='trf')return r.dir==='in'?a:-a;return -a;}
function stmCount56(){var n=0,i=0,e=0,t=0;STM.rows.forEach(function(r){if(!r.inc)return;n++;var v=Math.abs(parseAmt(r.amount));if(r.kind==='trf')t+=v;else if(r.kind==='in'||r.kind==='refund')i+=v;else e+=v;});return {n:n,i:i,e:e,t:t};}
function stmRecon(){
  if(STM.close==null||!isFinite(STM.close))return null;
  var e=STM.period.e,base=_abao54(STM.acc,e),add=0;
  STM.rows.forEach(function(r){if(r.inc&&r.date<=e)add+=stmEffect(r);});
  var app=Math.round((base+add)*100)/100,liab=stmIsLiab(),target=liab?-Math.abs(STM.close):STM.close;
  return {app:app,target:target,diff:Math.round((app-target)*100)/100,liab:liab};
}
