function stmGuess(g,hi){
  var ncol=0,rows=g.slice(hi+1,hi+30);g.slice(0,12).forEach(function(R){ncol=Math.max(ncol,(R||[]).length);});
  var sc=[];for(var c=0;c<ncol;c++){var nd=0,nn=0,len=0;rows.forEach(function(R){var v=(R||[])[c];if(stmDate(v,true))nd++;else if(/^[\s(+\-]*(RM|MYR|\$)?\s*[\d,]*\.?\d+\)?\s*(CR|DR|[+\-])?\s*$/i.test(cellS(v))&&cellS(v)!=='')nn++;else len+=cellS(v).length;});sc.push({nd:nd,nn:nn,len:len});}
  var date=-1,desc=-1,amt=-1,best=0;
  sc.forEach(function(x,c){if(x.nd>best){best=x.nd;date=c;}});best=-1;
  sc.forEach(function(x,c){if(c!==date&&x.len>best){best=x.len;desc=c;}});
  sc.forEach(function(x,c){if(c!==date&&c!==desc&&x.nn>0&&amt<0)amt=c;});
  return {date:date<0?0:date,desc:desc<0?1:desc,amt:amt};
}
