    +'<div><div class="mgr-lb">Or one amount column</div><select class="fin" id="mpAmt">'+colOpts(G.amt,1)+'</select></div><div><div class="mgr-lb">Balance (optional)</div><select class="fin" id="mpBal">'+colOpts(-1,1)+'</select></div></div>'
    +'<div class="f-row"><label>Dates are written as</label><select class="fin" id="mpFmt"><option value="dmy">Day / month / year</option><option value="mdy">Month / day / year</option></select></div>'
    +'<label class="stmopt" style="margin-bottom:10px"><input type="checkbox" id="mpSave" checked> Remember this layout for next time</label>'
    +'<button class="btn" data-act="stmmapgo">Use these columns</button>';
