    if(isCouple()&&realPeople().length>=2)h+='<div class="mgr-lb">People</div><div class="expchips">'+['all'].concat(sortedAlpha(realPeople())).map(function(p){return '<button class="chip'+(EXP2.ppl===p?' on':'')+'" data-act="expppl" data-v="'+esc(p)+'">'+(p==='all'?'Everyone':esc(p))+'</button>';}).join('')+'</div>';
