/* ---------- boot: load from IndexedDB (decrypting with the PIN if needed), then run queued start-up tasks ---------- */
function v57Go(json){
  /* boot only after every script has loaded: the IndexedDB read can finish while the page is
     still between <script> blocks, which used to boot with only some features installed */
  if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',function(){v57Go(json);},{once:true});return;}
  V57.pre=json;window.__BOOTED=1;
  try{boot();}catch(e){console.error('boot',e);}
  V57.booted=true;flushQueue57();stampInit();V57.last='';
  v57AiLoad();flush57();psApply();
}
function v57Start(){
  var ls=null,lsAt=0;try{ls=localStorage.getItem(LS_KEY);if(ls)lsAt=+((JSON.parse(ls).meta||{}).changedAt)||0;}catch(e){DIAG.note(e,"core/25-v1-57-security-storage-chunked:665");}
  _idbGet57('db').then(function(rec){
    if(rec&&rec.enc&&!(ls&&lsAt>=(+rec.at||0))){
      if(!c57ok()){v57Go(ls);return;}
      V57.encRec=rec;V57.bootCb=v57Go;lockShow('boot');return;
    }
    if(rec&&rec.json&&!(ls&&lsAt>=(+rec.at||0))){v57Go(rec.json);return;}
    v57Go(ls);
  }).catch(function(){v57Go(ls);});
}

