/* ---------------- shared-account permission levels (client-side; server rules are a production task) ---------------- */
function permFor59(n){
  if(!isCouple())return 'owner';
  var a=a59(n);if(!a)return 'owner';
  if(a.locked)return 'view';
  var me=meName();if(!me||!a.owner||a.recv)return 'owner';
  if(a.owner===me||String(a.owner).split(' & ').indexOf(me)>=0)return 'owner';
  if(a.vis==='me')return 'none';
  return a.partnerAccess||'add';
}
function canAdd59(n){var p=permFor59(n);return p!=='view'&&p!=='none';}
function canEditTxn59(t){
  if(!isCouple()||!t)return {ok:true};
  var me=meName(),res={ok:true,by:''},accs=[t.account];if(t.type==='Transfer'&&t.to&&!isRecvAcc(t.to))accs.push(t.to);
  var by=t.createdBy||t.person||'';
  for(var i=0;i<accs.length;i++){
    var n=accs[i],p=permFor59(n),a=a59(n)||{};
    if(p==='view')return {ok:false,msg:'You have View only access to '+(a.owner||'your partner')+'’s “'+n+'” account.'};
    if(p==='add'&&by!==me)return {ok:false,msg:'With Add transactions access you can change only the entries you created. This one was created by '+(by||'someone else')+'.'};
    if((p==='full'||p==='admin')&&by&&by!==me)res.by=by;
  }
  return res;
}
