  var split=F.gid||SPLIT.rows.some(function(r){return r.p&&r.p!==ownerOf(A)&&parseAmt(r.v)>0;});
  var owed=$('fOwedRow')&&!$('fOwedRow').hidden&&$('fOwed')&&$('fOwed').checked;
