/* ===================== v1.59 beta 3 · couple-mode folder-sharing prerequisite (plan 4.5 / 9.2 / 12.1) =====================
   Upgrades the beta 2 progress checklist into the full prerequisite flow from the revised plan ("Updated Folder Sharing"):
   · household owner role + provider choice (Google Drive / OneDrive)
   · Household-owner-created household folder + household code (stand-in for cmm-household.json in v1.60)
   · Guided read/write share · collaborator acceptance · access verification before activation
   · Pending until accepted AND access is confirmed · revoked access suspends editing (cached household read-only)
   · The app never creates a replacement household folder
   · Storage table gains the planned v1.60 row · optional onboarding step (plan 9.2) · version → beta 3 */
var V59B3={open:null};
var PDH_PROV={drive:'Google Drive',onedrive:'OneDrive'};
ICONS.key='<path d="m21 2-2 2m-7.61 7.61a5.5 5.5 0 1 1-7.78 7.78 5.5 5.5 0 0 1 7.78-7.78Zm0 0L15.5 7.5m0 0 3 3L22 7l-3-3m-3.5 3.5L19 4"/>';

/* ---------------- household folder state ---------------- */
function pdh59(){
  var v=m59();
  if(!v.pdh||typeof v.pdh!=='object')v.pdh={};
  var p=v.pdh;
  if(p.createdAt&&!p.code)p.code=pdhCode59();
  if(p.owner===undefined||p.owner===null)p.owner=meName()||'';
  return p;
}
function pdhCode59(){var cs='ABCDEFGHJKMNPQRSTUVWXYZ23456789',s='',i;for(i=0;i<8;i++)s+=cs.charAt(Math.floor(Math.random()*cs.length));return s.slice(0,4)+'-'+s.slice(4);}
function pdhProvName59(p){p=p||pdh59();return PDH_PROV[p.provider]||'Google Drive or OneDrive';}
function pdhIsOwner59(){var p=pdh59();return !p.owner||p.owner===(meName()||'');}
function pdhDay59(ts){var d=new Date(ts);return dLabelY(d.getFullYear()+'-'+pad2(d.getMonth()+1)+'-'+pad2(d.getDate()));}
function pdhState59(){
  var p=pdh59();
  if(!p.createdAt)return {cls:'',k:'none',t:'Not started',why:'The household owner creates the household folder in their own '+pdhProvName59(p)+'.'};
  if(p.missingAt)return {cls:'bad',k:'suspended',t:'Editing suspended',why:'Folder access was lost or revoked. The cached household is read-only until access is restored. The app never creates a replacement folder.'};
  if(!p.sharedAt)return {cls:'warn',k:'setup',t:'Folder created · not shared yet',why:'Share the folder with '+esc(partnerName())+' using read/write access before household sync can be activated.'};
  if(!p.acceptedAt)return {cls:'warn',k:'pending',t:'Pending · awaiting collaborator',why:esc(p.email||partnerName())+' has not accepted the invitation yet, so shared editing stays off.'};
  if(!p.verifiedAt)return {cls:'warn',k:'pending',t:'Pending · access not confirmed',why:'Confirm the household code from the shared folder to activate shared editing.'};
  return {cls:'ok',k:'active',t:'Access confirmed',why:'Shared editing is active for this household folder. Revision checks and conflict review arrive with v1.60 sync.'};
}
function pdhActive59(){var p=pdh59();return !!(p.createdAt&&p.sharedAt&&p.acceptedAt&&p.verifiedAt&&!p.missingAt);}

/* ---------------- actions ---------------- */
function pdhPaint59(){try{renderStore59();}catch(e){DIAG.note(e,"15-v159-b3-folder-sharing:47");}if(AU.mode==='hhfolder'){try{rAuthHHF59();}catch(e){DIAG.note(e,"15-v159-b3-folder-sharing:47");}}}
function pdhProv59(k){var p=pdh59();if(p.createdAt){toast('The provider is fixed once the household folder exists.');return;}p.provider=k;save();pdhPaint59();}
function pdhCreate59(){
  var p=pdh59();
  if(p.missingAt){toast('Reconnect the existing folder — the app never creates a replacement.');return;}
  if(p.createdAt){toast('The household folder already exists.');return;}
  p.owner=meName()||p.owner||'';p.folder='Couple Money Manager';p.createdAt=Date.now();p.code=pdhCode59();
  save();pdhPaint59();toast('Household folder created in '+pdhProvName59(p));
}
function pdhShare59(){
  var p=pdh59();
  if(!p.createdAt){toast('Create the household folder first.');return;}
  if(!p.email||!emailOK(p.email)){toast('Enter your partner’s email first.');return;}
  if(!p.sharedAt){p.sharedAt=Date.now();save();toast('Folder shared with '+p.email+' · read/write');}
  pdhPaint59();
}
function pdhAccept59(){
  var p=pdh59();
  if(pdhIsOwner59()&&!p.sharedAt){toast('Share the folder first.');return;}
  p.acceptedAt=Date.now();save();pdhPaint59();toast('Invitation accepted ✓');
}
function pdhVerify59(val){
  var p=pdh59();
  if(!p.acceptedAt){toast('The collaborator must accept the invitation first.');return;}
  var c=(val||'').trim().toUpperCase();
  if(!c){toast('Enter the household code.');return;}
  if(pdhIsOwner59()&&p.code&&c!==String(p.code).toUpperCase()){toast('That code does not match this household.');return;}
  if(!pdhIsOwner59())p.code=c; /* on this device the code arrives from the shared folder */
  p.verifiedAt=Date.now();delete p.missingAt;save();pdhPaint59();toast('Access confirmed · shared editing active');
}
function pdhMissing59(){
  askConfirm('Mark the household folder as unreachable or revoked? Editing is suspended and the cached household becomes read-only until access is restored. The app will not create a replacement folder.','Suspend editing',function(){
    var p=pdh59();p.missingAt=Date.now();delete p.verifiedAt;save();pdhPaint59();
    toast('Editing suspended · cached household is read-only');
  });
}
function pdhRestore59(){var p=pdh59();delete p.missingAt;save();pdhPaint59();toast('Folder reachable again · confirm access to resume shared editing');}
function pdhEmail59(val){var p=pdh59();p.email=(val||'').trim();save();}

