/* ---------- 4 · navigation history for back buttons (D10) ---------- */
var NAVH=[];
var _sp10=SCREEN.upTo('showPage',160009942),_sg10=B3.setGo,_sb10=B3.setBack;
window._sb10=_sb10; /* used by js/screens */
function snapD(){return {level:DRILL.level,acc:DRILL.acc,person:DRILL.person,month:DRILL.month,cat:DRILL.cat,mode:DRILL.mode,expDay:DRILL.expDay,cyc:DRILL.cyc};}
B10.cur=function(){
  if(B3.open)return {t:'set',k:B3.cur||''};
  if(REPORT.open)return {t:'rep',k:B10.lastRep||''};
  if(DRILL.open){
    if(DRILL.level==='list')return {t:'view',v:VIEWNAV.cur||'overview'};
    return {t:'drill',d:snapD(),v:VIEWNAV.cur||'overview'};
  }
  return {t:'view',v:VIEWNAV.cur||'overview'};
};
function same10(a,b){return JSON.stringify(a)===JSON.stringify(b);}
function navhPush(e){
  if(!e)return;
  var last=NAVH[NAVH.length-1];
  if(last&&same10(last,e))return;
  if(last&&last.t==='view'&&e.t==='view'&&last.v===e.v)return;
  NAVH.push(e);
  if(NAVH.length>60)NAVH.shift();
}
B10.navBack=function(fb){
  if(B10.rest){if(fb)fb();return;}
  var cur=B10.cur();
  while(NAVH.length){
    var e=NAVH.pop();
    if(!same10(e,cur)){B10.go(e);return;}
  }
  if(fb)fb();
};
B10.go=function(e){
  B10.rest=true;
  try{
    if(e.t==='set'){
      if(REPORT.open)closeReport();
      if(DRILL.open){DRILL.open=false;DRILL.acc='';DRILL.person='';hidePage();}
      _sb10(); gotoView('settings');
      if(B3.cur!==e.k)_sg10(e.k);
    }else if(e.t==='rep'){
      if(B3.open)_sb10();
      if(DRILL.open){DRILL.open=false;DRILL.acc='';DRILL.person='';hidePage();}
      gotoView(VIEWNAV.cur||'overview'); openReport(e.k);
    }else if(e.t==='drill'){
      if(B3.open)_sb10();
      if(REPORT.open)closeReport();
      gotoView(e.v||'overview');
      Object.assign(DRILL,e.d||{}); renderDrill(); _sp10();
    }else{
      if(B3.open)_sb10();
      if(REPORT.open)closeReport();
      if(DRILL.open){DRILL.open=false;DRILL.acc='';DRILL.person='';hidePage();}
      gotoView(e.v||'overview');
    }
  }finally{ setTimeout(function(){B10.rest=false;},0); }
};
SCREEN.on('gotoView',160011862);
SCREEN.on('showPage',160012039);
SCREEN.on('openReport',160012126);
B3.setGo=function(k){
  /* defensive: switching subs directly must not annihilate the section left in the sub-page */
  if(B3.open&&B3.cur&&B3.cur!==k){try{_sb10();}catch(e){DIAG.note(e,"29-v160-b10-drilldowns-nav:250");}}
  if(!B10.rest){
    var wasOpen=B3.open;
    /* the settings root reached just to open a sub is a pass-through — record the sub itself */
    if(!wasOpen&&VIEWNAV.cur==='settings')navhPush({t:'view',v:'settings'});
    navhPush({t:'set',k:k});
  }
  _sg10(k);
  try{navSync();}catch(e){DIAG.note(e,'b25:setGo');}
  try{if(k==='lists'&&$('setTitle'))$('setTitle').textContent='Manage Lists';}catch(e){DIAG.note(e,"29-v160-b10-drilldowns-nav:258");}
};
B3.setBack=function(){
  /* the on-screen Back of a Settings page always returns to the Settings home */
  if(B10.rest){_sb10();return;}
  while(NAVH.length&&NAVH[NAVH.length-1].t==='set')NAVH.pop();
  if(NAVH.length&&NAVH[NAVH.length-1].t==='view'&&NAVH[NAVH.length-1].v==='settings')NAVH.pop();
  _sb10();
  try{navSync();}catch(e){DIAG.note(e,'b25:setBack');}
};
