V63.favAdd=function(k){
  try{
    var L=[];try{L=JSON.parse(localStorage.getItem('v63recent')||'[]');}catch(e){DIAG.note(e,"35-v160-b16-insights-reports:642");}
    L=L.filter(function(x){return x!==k;});L.unshift(k);L=L.slice(0,4);
    localStorage.setItem('v63recent',JSON.stringify(L));
  }catch(e){DIAG.note(e,"35-v160-b16-insights-reports:645");}
};
function favChips16(){
  var L=[];try{L=JSON.parse(localStorage.getItem('v63recent')||'[]');}catch(e){DIAG.note(e,"35-v160-b16-insights-reports:648");}
  if(!L.length)return '<div class="help small" style="margin:0 0 2px">Your recently opened reports appear here.</div>';
  return L.map(function(k){
    var t=(REP_TITLES[k]||'').replace(/<svg[\s\S]*?<\/svg>/,'').trim()||k;
    return '<button class="chip" data-act="v63rep" data-k="'+esc(k)+'">'+esc(t)+'</button>';
  }).join('');
}
function renderReports(){
  var t=$('v63tiles');if(!t)return;
  t.innerHTML=FAM16.map(famTile16).join('');
  var f=$('v63fav');if(f)f.innerHTML=favChips16();
}

