DYNF.f_couple=function(){return '<div class="card"><h2>'+ico('users')+' Couple reports</h2>'+V63.FAMROWS.f_couple.map(function(r){return famRow16(r[0],r[1],r[2],r[3]);}).join('')+'</div>';};
