DYNF.v_alloc=function(){
  var asd=asAt26(),M=V63.calc.mix(whoOK(),asd),h=segbar16(M.segs,M.total);
  M.segs.forEach(function(s,i){
    h+='<div class="mgr-lb" style="margin-top:10px">'+esc(s.k)+' · '+money(s.v)+' · '+(M.total?Math.round(s.v/M.total*100):0)+'%</div>';
    s.rows.forEach(function(x){h+='<button class="trow" data-act="acc" data-n="'+esc(x.name)+'"><span class="lb">'+esc(x.name)+'<small>'+esc(x.type||'')+(x.owner?' · '+esc(x.owner):'')+'</small></span><span class="amt2'+(x.v<0?' neg':'')+'">'+money(x.v)+'</span></button>';});
  });
  return card16(ico('pie')+' Asset mix <span class="sub">as at '+dLabelY(asd)+' · '+whoLabel()+'</span>',h+'<div class="help small" style="margin-top:8px">Uses the values you entered and your share of anything owned jointly. Sold items drop out from the date sold.</div>');
};
DYNF.v_liabred=function(){
  var td=asAt26(),D=V63.calc.debts(whoOK(),td),d6=addDaysISO(td.slice(0,8)+'01',-1);
  var h='';
  D.segs.forEach(function(s){
    h+='<div class="mgr-lb" style="margin-top:10px">'+esc(s.k)+' · '+money(s.v)+'</div>';
    s.rows.forEach(function(x){
      var b6=accountBalAsOf(x.name,d6),now=-x.v;
      var moved=Math.round((b6-now)*100)/100;
      h+='<div class="fline"><span>'+esc(x.name)+'</span><span style="text-align:right"><b>'+money(now)+'</b>'+(moved>0.004?' <small class="pos">▼ '+money(moved)+' in 6 months</small>':'')+'</span></div>';
    });
  });
  var tr=[],k;
  for(k=5;k>=0;k--){var rr=perRange(PER.off-k);tr.push({lb:rr.short,v:V63.calc.debts(whoOK(),rr.e<todayISO()?rr.e:todayISO()).total,s:rr.s,e:rr.e,full:rr.label});}
  h+='<div class="mgr-lb" style="margin-top:10px">Total debts · last 6 '+perWord()+'s</div><div class="chart-scroll">'+svgNet(tr.map(function(x){return {lb:x.lb,net:-x.v,full:x.full,s:x.s,e:x.e};}))+'</div>';
  return card16(ico('down')+' Debt reduction',h);
};
DYNF.v_drivers=function(){
  var D=V63.calc.drivers(perRange());
  var h=D.rows.map(function(x){return '<div class="fline"><span>'+esc(x.label)+'</span><b class="'+(x.v<0?'neg':'pos')+'">'+sgn16(x.v)+'</b></div>';}).join('')
    +'<div class="fline eq"><span><b>Total movement</b></span><b class="'+(D.total<0?'neg':'pos')+'">'+sgn16(D.total)+'</b></div>'
    +'<div class="help small" style="margin-top:6px">'+V63.driversNote(D)+' Value adjustments are non-cash — they never create income or spending.</div>';
  return card16(ico('trend')+' Wealth drivers <span class="sub">'+esc(perRange().label)+'</span>',h);
};
DYNF.v_health=function(){
  var H=V63.calc.health(perRange());
  var h='<div class="kpis">'+kpi('Emergency fund',H.efMonths==null?'—':Math.round(H.efMonths*10)/10+' months','')+kpi('Debt ratio',H.debtRatio==null?'—':pct16(H.debtRatio),'')+kpi('Savings rate',H.savingsRate==null?'—':pct16(H.savingsRate),H.savingsRate!=null&&H.savingsRate<0?'neg':'pos')+'</div>'
    +'<div class="fline"><span>Liquid money · as at '+esc(dLabelY(asAt26()))+'</span><b>'+money(H.liquid)+'</b></div>'
    +'<div class="fline"><span>Average monthly spending · 3 months before</span><b>'+money(H.avgMonth)+'</b></div>'
    +'<div class="fline"><span>Income vs spending · '+esc(perRange().label)+'</span><b>'+money(H.income)+' vs '+money(H.spending)+'</b></div>'
    +'<div class="help small" style="margin-top:8px">Emergency fund coverage = eligible liquid funds ÷ average essential monthly spending. Debt ratio = total debts ÷ total recorded assets. Savings rate = monthly surplus ÷ income.</div>';
  return card16(ico('heart')+' Financial health <span class="sub">'+esc(perRange().label)+'</span>',h);
};
DYNF.v_income=function(){
  var r=perRange(),cb=catBreakdown(perTx(r),'Income').filter(function(x){return x.value>0;}).sort(function(a,b){return b.value-a.value;});
  if(!cb.length)return '<div class="card"><h2>'+ico('trend')+' Income sources</h2><div class="help">No income recorded in this period.</div></div>';
  var tot=cb.reduce(function(s,x){return s+x.value;},0),Pv=catBreakdown(perTx(perRange(PER.off-1)),'Income');
  var h='<div class="kpis">'+kpi('Income',money(tot),'pos')+kpi('Sources',String(cb.length),'')+kpi('Top share',pct16(cb[0].value/tot),'')+'</div>';
  cb.forEach(function(x){h+='<div class="fline"><span>'+esc(x.label)+'</span><span style="text-align:right"><b>'+money(x.value)+'</b> <small style="color:var(--muted)">'+Math.round(x.value/tot*100)+'% · '+pctChg(x.value,Pv[x.label]||0)+' vs last</small></span></div>';});
  return card16(ico('trend')+' Income sources <span class="sub">'+esc(r.label)+'</span>',h);
};
DYNF.v_ncf=function(){
  var r=perRange(),f=V63.calc.flow(r),L=perTx(r),i=sumT(L,'Income'),e=sumT(L,'Expense');
  var h='<div class="kpis">'+kpi('Income',money(i),'pos')+kpi('Spending',money(e),'neg')+kpi('Surplus',sgn16(i-e),i-e<0?'neg':'pos')+kpi('Net cash flow',sgn16(f.ncf),f.ncf<0?'neg':'pos')+'</div>';
  var rows=[['Cash spending',-f.spend],['Loan principal',-f.loanP],['Card payments',-f.cardP],['Investments',-f.invest],['Asset purchases',-f.assetBuy],['Other movements',f.other]];
  rows.filter(function(x){return Math.abs(x[1])>0.004;}).forEach(function(x){h+='<div class="fline"><span>'+x[0]+'</span><b class="'+(x[1]<0?'neg':'pos')+'">'+sgn16(x[1])+'</b></div>';});
  return card16(ico('swap')+' Net cash flow <span class="sub">'+esc(r.label)+'</span>',h);
};
DYNF.v_cattrend=function(){
  var tr=periodsBack(6),tops={},k;
  tr.forEach(function(rr,i){catBreakdown(perTx(rr),'Expense').forEach(function(x){(tops[x.label]=tops[x.label]||[])[i]=x.value;});});
  var rows=Object.keys(tops).map(function(c){var s=0;for(k=0;k<6;k++)s+=(tops[c][k]||0);return {c:c,s:s,a:tops[c]};}).sort(function(x,y){return y.s-x.s;}).slice(0,6);
  if(!rows.length)return '<div class="card"><h2>'+ico('chart')+' Category trends</h2><div class="help">No spending in the last 6 '+perWord()+'s.</div></div>';
  var h='<table class="rtab"><thead><tr><th>Category</th>'+tr.map(function(x){return '<th class="r">'+esc(x.short)+'</th>';}).join('')+'</tr></thead><tbody>';
  rows.forEach(function(rw){
    h+='<tr><td><b>'+esc(rw.c)+'</b></td>'+tr.map(function(x,i){var v=rw.a[i]||0;return '<td class="r'+(v?' neg':' muted')+'">'+(v?fmt(v):'·')+'</td>';}).join('')+'</tr>';
  });
  return card16(ico('chart')+' Category trends <span class="sub">last 6 '+perWord()+'s</span>',h+'</tbody></table>');
};
DYNF.v_forecast=function(){
  var tr=periodsBack(3),net=tr.reduce(function(s,x){return s+x.net;},0)/Math.max(1,tr.length);
  var liq=0;Object.keys(V63.liqSet(whoOK())).forEach(function(n){var b=accountBalAsOf(n,todayISO());if(isFinite(b))liq+=b;});
  var f3=liq+net*3,f6=liq+net*6;
  var h='<div class="kpis">'+kpi('Avg net movement · 3 '+perWord()+'s',sgn16(net),net<0?'neg':'pos')+kpi('Liquid now',money(liq),'')+kpi('In 6 '+perWord()+'s',sgn16(f6),f6<0?'neg':'pos')+'</div>'
    +'<div class="fline"><span>Projected liquid · 3 '+perWord()+'s ahead</span><b class="'+(f3<0?'neg':'')+'">'+money(f3)+'</b></div>'
;
  return card16(ico('cal')+' Forecast',h);
};
DYNF.v_contrib=function(){
  var r=perRange(),L=DB.txns.filter(function(t){return t.date>=r.s&&t.date<=r.e&&t.type!=='Transfer';});
  var paid={},inc={};
  L.forEach(function(t){var o=ownerOf(t.account)||t.person||'No account owner';if(t.type==='Expense'&&t.group)paid[o]=(paid[o]||0)+t.amount;if(t.type==='Income'){var ip=t.person||o;inc[ip]=(inc[ip]||0)+t.amount;}});
  var ppl=sortedAlpha(DB.people),h='';
  if(!ppl.length)ppl=['No account owner'];
  h+='<div class="mgr-lb">Shared expenses paid · '+esc(r.label)+'</div>';
  ppl.forEach(function(p){h+='<div class="fline"><span>'+esc(p)+'</span><b>'+(paid[p]?money(paid[p]):'—')+'</b></div>';});
  h+='<div class="mgr-lb" style="margin-top:10px">Household income recorded</div>';
  ppl.forEach(function(p){h+='<div class="fline"><span>'+esc(p)+'</span><b class="pos">'+(inc[p]?money(inc[p]):'—')+'</b></div>';});
  return card16(ico('users')+' Contribution',h);
};
DYNF.v_joint=function(){
  var td=todayISO(),pts=[],k;
  for(k=5;k>=0;k--){var rr=perRange(PER.off-k);pts.push({lb:rr.short,v:nwAt(rr.e<td?rr.e:td,'couple').net});}
  var gl=goalsList().filter(function(g){return g.owner==='couple';});
  var h='<div class="mgr-lb">Household net worth · last 6 '+perWord()+'s</div><div class="chart-scroll">'+svgLine59(pts)+'</div>'
    +(gl.length?'<div class="mgr-lb" style="margin-top:10px">Shared goals</div><div class="dayg">'+gl.map(goalHTML).join('')+'</div>':'');
  return card16(ico('users')+' Joint progress',h);
};
DYNF.v_fundhist=function(){
  var gl=[];goalGroups().forEach(function(x){gl=gl.concat(x.l);});
  if(!gl.length)return '<div class="card"><h2>'+ico('clock')+' Funding history</h2><div class="help">No saving goals yet. Add one from Insights → Goals.</div></div>';
  var h=gl.map(function(g){return '<div class="fline"><span>'+esc(g.name)+'</span><b>'+money(goalSaved(g))+' of '+money(g.target)+'</b></div>';}).join('')
    +'<div class="help small" style="margin-top:8px">Contributions are tracked as running totals per goal; individual dated funding entries are not recorded yet.</div>';
  return card16(ico('clock')+' Funding history',h);
};
DYNF.v_goalcast=function(){
  var gl=[];goalGroups().forEach(function(x){gl=gl.concat(x.l);});
  if(!gl.length)return '<div class="card"><h2>'+ico('cal')+' Forecast completion</h2><div class="help">No saving goals yet.</div></div>';
  var td=todayISO(),h='';
  gl.forEach(function(g){
    var sv=goalSaved(g),left=Math.max(0,(+g.target||0)-sv);
    if(g.due&&left>0.004){
      var mo=Math.max(1,Math.round((Date.parse(g.due)-Date.parse(td))/864e5/30));
      h+='<div class="fline"><span>'+esc(g.name)+'<small>'+money(left)+' to go · by '+dLabelY(g.due)+'</small></span><b>'+money(left/mo)+' / month</b></div>';
    }else if(left<=0.004)h+='<div class="fline"><span>'+esc(g.name)+'</span><b class="pos">Reached ✓</b></div>';
    else h+='<div class="fline"><span>'+esc(g.name)+'</span><b class="muted">Add a target date</b></div>';
  });
  return card16(ico('cal')+' Forecast completion',h+'<div class="help small" style="margin-top:8px">Required monthly saving = remaining amount ÷ months until the target date.</div>');
};
function valRows16(pred,ic,title){
  var accs=DB.accounts.filter(function(a){return pred(a)&&ownerHas(a.owner,whoOK());});
  if(!accs.length)return '<div class="card"><h2>'+ico(ic)+' '+title+'</h2><div class="help">No '+title.toLowerCase()+' accounts yet. Add one from Accounts → Add account.</div></div>';
  var tot=0,h='';
  accs.sort(function(x,y){return alphasort(x.name,y.name);}).forEach(function(a){
    var v=accountBalAsOf(a.name,todayISO());if(isFinite(v))tot+=v;
    var st=V63.statusOf(a);
    h+='<button class="trow" data-act="acc" data-n="'+esc(a.name)+'"><span class="lb">'+esc(a.name)+'<small>'+esc(a.type||'')+(a.propType?' · '+esc(a.propType):'')+(a.vehicleType?' · '+esc(a.vehicleType):'')+(a.propUse?' · '+esc(a.propUse):'')+' · '+esc(a.owner||'No account owner')+(st!=='active'?' · '+esc(st):'')+'</small></span><span class="amt2">'+money(v)+'</span></button>';
  });
  return card16(ico(ic)+' '+title+' <span class="sub">'+money(tot)+'</span>',h+'<div class="help small" style="margin-top:6px">'+DISC59+'</div>');
}
DYNF.v_money=function(){
  var asd=asAt26(),names=Object.keys(V63.liqSet(whoOK())),tot=0,h='';
  names.sort().forEach(function(n){var b=accountBalAsOf(n,asd);if(isFinite(b))tot+=b;h+='<button class="trow" data-act="acc" data-n="'+esc(n)+'"><span class="lb">'+esc(n)+'<small>Bank, cash or e-Wallet</small></span><span class="amt2'+(b<0?' neg':'')+'">'+money(b)+'</span></button>';});
  if(!names.length)return '<div class="card"><h2>'+ico('cash')+' Cash position</h2><div class="help">No bank, cash or e-Wallet accounts yet.</div></div>';
  h+='<div class="fline eq" style="margin-top:8px"><span><b>Cash position</b></span><b>'+money(tot)+'</b></div>';
  return card16(ico('cash')+' Cash position <span class="sub">as at '+dLabelY(asd)+'</span>',h);
};
DYNF.v_invest=function(){return valRows16(function(a){return a.type==='Investment';},'trend','Investments');};
DYNF.v_props=function(){
  var h=valRows16(function(a){return a.type==='Property';},'home','Properties');
  var accs=DB.accounts.filter(function(a){return a.type==='Property'&&ownerHas(a.owner,whoOK());});
  accs.forEach(function(a){
    var loans=(a.linkedLoans||[]).map(function(n){return a59(n);}).filter(function(l){return l&&isLoan(l)&&ownerHas(l.owner,whoOK());});
    if(!loans.length)return;
    var debt=0;loans.forEach(function(l){var b=accountBalAsOf(l.name,todayISO());if(isFinite(b))debt+=Math.abs(b);});
    var v=accountBalAsOf(a.name,todayISO());
    var basis=(+a.ownPct>0&&+a.ownPct<100)?((a.ownMode||'owned-share')==='gross'?'Your/household share · '+a.ownPct+'%':'Full property value'):((a.ownMode||'owned-share')==='gross'&&+a.ownPct===100?'Full property value':'Household share');
    h+='<div class="card"><h2>'+ico('home')+' '+esc(a.name)+' <span class="sub">derived summary</span></h2>'
      +'<div class="fline"><span>Recorded value · '+esc(basis)+'</span><b>'+money(v)+'</b></div>'
      +loans.map(function(l){var b=accountBalAsOf(l.name,todayISO());return '<button class="fline" data-act="acc" data-n="'+esc(l.name)+'" style="width:100%;text-align:left"><span>Less '+esc(l.name)+'</span><b class="neg">\u2212 '+money(Math.abs(isFinite(b)?b:0))+'</b></button>';}).join('')
      +'<div class="fline eq"><span><b>Net property position</b></span><b class="'+(v-debt<0?'neg':'pos')+'">'+money(v-debt)+'</b></div>'
      +'<div class="help small" style="margin-top:6px">For comparison only — the property keeps the value you entered and the loan stays a separate debt.</div></div>';
  });
  return h;
};
DYNF.v_veh=function(){
  var h=valRows16(function(a){return a.type==='Vehicle';},'car','Vehicles');
  var accs=DB.accounts.filter(function(a){return a.type==='Vehicle'&&ownerHas(a.owner,whoOK());});
  accs.forEach(function(a){
    var loans=DB.accounts.filter(function(l){return isLoan(l)&&l.linkedAsset===a.name&&ownerHas(l.owner,whoOK());});
    if(!loans.length)return;
    var debt=0;loans.forEach(function(l){var b=accountBalAsOf(l.name,todayISO());if(isFinite(b))debt+=Math.abs(b);});
    var v=accountBalAsOf(a.name,todayISO());
    h+='<div class="card"><h2>'+ico('car')+' '+esc(a.name)+' <span class="sub">derived summary</span></h2>'
      +'<div class="fline"><span>Recorded value</span><b>'+money(v)+'</b></div>'
      +loans.map(function(l){var b=accountBalAsOf(l.name,todayISO());return '<button class="fline" data-act="acc" data-n="'+esc(l.name)+'" style="width:100%;text-align:left"><span>Less '+esc(l.name)+'</span><b class="neg">\u2212 '+money(Math.abs(isFinite(b)?b:0))+'</b></button>';}).join('')
      +'<div class="fline eq"><span><b>Net vehicle position</b></span><b class="'+(v-debt<0?'neg':'pos')+'">'+money(v-debt)+'</b></div></div>';
  });
  return h;
};
DYNF.v_business=function(){
  var accs=DB.accounts.filter(function(a){return a.v63cat==='Businesses'&&ownerHas(a.owner,whoOK());});
  if(!accs.length)return '<div class="card"><h2>'+ico('briefcase')+' Businesses</h2><div class="help">No business accounts yet. Record company shares or partnership interest as an account under <b>Other</b> and tag it Businesses when you add it.</div></div>';
  var tot=0,h=accs.map(function(a){var v=accountBalAsOf(a.name,todayISO());if(isFinite(v))tot+=v;return '<div class="fline"><span>'+esc(a.name)+'</span><b>'+money(v)+'</b></div>';}).join('');
  return card16(ico('briefcase')+' Businesses <span class="sub">'+money(tot)+'</span>',h);
};
DYNF.v_recv=function(){
  var ls=ledgers().filter(function(l){return l.amt>=0.005;});
  var recvAccs=DB.accounts.filter(function(a){return isRecvAcc(a.name)&&!ls.some(function(l){return l.name===a.name;});});
  if(!ls.length&&!recvAccs.length)return '<div class="card"><h2>'+ico('undog')+' Money owed to me</h2><div class="help">Nothing owed to you right now. Split bills create balances here automatically.</div></div>';
  var h=ls.map(function(l){return '<button class="fline" data-act="rep" data-k="settle" style="width:100%;text-align:left"><span>'+esc(l.debtor)+' owes '+esc(l.creditor)+'</span><b class="neg">'+money(l.amt)+'</b></button>';}).join('');
  recvAccs.forEach(function(a){var b=accountBalAsOf(a.name,todayISO());h+='<div class="fline"><span>'+esc(a.name)+'</span><b>'+money(Math.abs(isFinite(b)?b:0))+'</b></div>';});
  return card16(ico('undog')+' Money owed to me',h);
};
DYNF.v_valhist=function(){
  var accs=DB.accounts.filter(function(a){return isVal(a)&&(a.vals||[]).length&&ownerHas(a.owner,whoOK());});
  if(!accs.length)return '<div class="card"><h2>'+ico('nw')+' Recorded value history</h2><div class="help">No value adjustments recorded yet. Open an asset account and tap <b>Update value</b>.</div></div>';
  var h='';
  accs.forEach(function(a){
    h+='<div class="mgr-lb" style="margin-top:10px">'+esc(a.name)+' <span style="text-transform:none;font-weight:600">· purchase '+money(purchaseOf(a))+(a.purchaseDate?' · '+dLabelY(a.purchaseDate):'')+'</span></div>';
    (a.vals||[]).slice().sort(function(x,y){return x.date<y.date?1:-1;}).forEach(function(v){
      var d=Math.round((v.value-valueAsOf(a,addDaysISO(v.date,-1)))*100)/100;
      h+='<div class="fline"><span>'+dLabelY(v.date)+(v.note?' · '+esc(v.note):'')+'</span><b>'+money(v.value)+(Math.abs(d)>0.004?' <small class="'+(d<0?'neg':'pos')+'">('+sgn16(d)+')</small>':'')+'</b></div>';
    });
  });
  return card16(ico('nw')+' Recorded value history',h+'<div class="help small" style="margin-top:8px">Dated adjustments change Net Worth from their effective date. They never create income, spending or cash flow.</div>');
};
DYNF.v_outstd=function(){
  var asd=asAt26(),D=V63.calc.debts(whoOK(),asd),h='';
  if(!D.total)return '<div class="card"><h2>'+ico('card')+' Debt mix</h2><div class="help">No debt accounts. That is a good place to be.</div></div>';
  D.segs.forEach(function(s){h+='<div class="mgr-lb" style="margin-top:8px">'+esc(s.k)+'</div>';s.rows.forEach(function(x){h+='<button class="trow" data-act="acc" data-n="'+esc(x.name)+'"><span class="lb">'+esc(x.name)+'<small>'+esc(x.type||'')+'</small></span><span class="amt2 neg">'+money(-x.v)+'</span></button>';});});
  h+='<div class="fline eq" style="margin-top:8px"><span><b>Total owed</b></span><b class="neg">'+money(D.total)+'</b></div>';
  return card16(ico('card')+' Debt mix <span class="sub">as at '+dLabelY(asd)+'</span>',h);
};
function liabFlow16(r){
  var who=whoOK(),out=0,int2=0;
  DB.txns.forEach(function(t){
    if(t.date<r.s||t.date>r.e)return;
    if(who!=='couple'){var o=ownerOf(t.account);if(o&&o!==who&&String(o).split(' & ').indexOf(who)<0)return;}
    if(t.type==='Transfer'&&t.to){var a=a59(t.to);if(a&&(isLoan(a)||accTypeKind(a.type)==='liability'))out+=t.amount;}
    if(t.type==='Expense'&&B7.excl(t))int2+=t.amount;
  });
  return {principal:Math.round(out*100)/100,interest:Math.round(int2*100)/100};
}
DYNF.v_prinrep=function(){
  var r=perRange(),f=liabFlow16(r),tr=periodsBack(6),pts=tr.map(function(x){return {lb:x.short,net:-liabFlow16(x).principal,full:x.label,s:x.s,e:x.e};});
  var h='<div class="kpis">'+kpi('Principal repaid',money(f.principal),'pos')+kpi('Interest & charges',money(f.interest),'neg')+'</div>'
    +'<div class="mgr-lb" style="margin-top:8px">Principal repaid · last 6 '+perWord()+'s</div><div class="chart-scroll">'+svgNet(pts)+'</div>'
    +'<div class="help small" style="margin-top:6px">The part of each repayment that reduces what I owe. Interest is a cost — it doesn\u2019t reduce the balance.</div>';
  return card16(ico('down')+' Principal repaid <span class="sub">'+esc(r.label)+'</span>',h);
};
DYNF.v_instal=function(){
  var accs=DB.accounts.filter(function(a){return isLoan(a)&&+a.instalment>0&&ownerHas(a.owner,whoOK());});
  if(!accs.length)return '<div class="card"><h2>'+ico('cal')+' Remaining instalments</h2><div class="help">Set a fixed instalment amount on a loan or hire-purchase account to see the months remaining.</div></div>';
  var h='';
  accs.forEach(function(a){
    var bal=Math.abs(accountBalAsOf(a.name,todayISO())||0),n=Math.ceil(bal/a.instalment);
    var finish=n<600?dLabelY(addDaysISO(todayISO(),n*30)):'—';
    h+='<div class="fline"><span>'+esc(a.name)+'<small>'+money(bal)+' left · '+money(a.instalment)+' / '+(a.freq==='w'?'week':a.freq==='f'?'fortnight':a.freq==='q'?'quarter':a.freq==='y'?'year':'month')+'</small></span><b>~'+n+' · '+finish+'</b></div>';
  });
  return card16(ico('cal')+' Remaining instalments',h+'<div class="help small" style="margin-top:8px">Estimate at a steady instalment — early repayments shorten it.</div>');
};
DYNF.v_repaytrend=function(){
  var tr=periodsBack(6),p=tr.map(function(x){return {lb:x.short,net:liabFlow16(x).principal,full:x.label,s:x.s,e:x.e};}),i=tr.map(function(x){return {lb:x.short,net:liabFlow16(x).interest,full:x.label,s:x.s,e:x.e};});
  var h='<div class="mgr-lb">Principal · last 6 '+perWord()+'s</div><div class="chart-scroll">'+svgNet(p)+'</div>'
    +'<div class="mgr-lb" style="margin-top:8px">Interest &amp; charges</div><div class="chart-scroll">'+svgNet(i)+'</div>';
  return card16(ico('chart')+' Repayment trend',h);
};
