    +'<div class="mgr-lb">Registration / identifier (optional)</div><input class="fin" id="v16_reg" value="'+esc(a.regId||'')+'" placeholder="Plate or reference — never required" style="margin-bottom:7px">'
    +'<div class="mgr-lb">Notes (optional)</div><input class="fin" id="v16_notes" value="'+esc(a.notes||'')+'" placeholder="Anything worth remembering">'
    +'</details>';
