/* apply extra fields on EDIT save (pre-captured — the core save re-renders the manager) */
var _ms16=mgrSave;
mgrSave=function(el){
  var k=el&&el.dataset.k,cap=null;
  try{
    if(MGR.kind==='accs'&&k&&$('e16wrap')){
      cap={
        loans:[].slice.call(document.querySelectorAll('#e16wrap input[name=p16_loan]:checked')).map(function(c){return c.value;}),
        pd:($('p16_pd')||{}).value||'', use:($('p16_use')||{}).value||'', notes:($('p16_notes')||{}).value||'',
        partial:!!($('p16_partial')||{}).checked, pct:parseAmt(($('p16_pct')||{}).value), basis:(($('p16_basis')||{}).value)||'owned-share',
        av:parseAmt(($('p16_av')||{}).value), avd:($('p16_avd')||{}).value||'',
        vpd:($('v16_pd')||{}).value||'', reg:($('v16_reg')||{}).value||'', vnotes:($('v16_notes')||{}).value||''
      };
    }
  }catch(e){DIAG.note(e,"35-v160-b16-insights-reports:1174");}
  _ms16.apply(this,arguments);
  try{
    if(!cap)return;
    var a=a59(k);if(!a)return;
    if(a.type==='Property'){
      a.propType=V63.propTypeSel||a.propType||'Other property';
      a.purchaseDate=cap.pd||'';
      a.propUse=cap.use||'';
      a.notes=cap.notes||'';
      a.linkedLoans=cap.loans;
      cap.loans.forEach(function(ln){var l=a59(ln);if(l&&!l.linkedAsset)l.linkedAsset=a.name;});
      a.ownPct=cap.partial?((cap.pct>0&&cap.pct<=100)?Math.round(cap.pct*100)/100:100):100;
      a.ownMode=cap.basis||'owned-share';
      var lv=lastVal(a);
      if(cap.av>0&&cap.avd&&(!lv||lv.value!==cap.av||lv.date!==cap.avd)){
        var cur0=valueAsOf(a,todayISO());
        if(Math.abs(cap.av-cur0)>0.004){valHist(a).push({date:cap.avd,value:Math.round(cap.av*100)/100,note:'Updated from account details',by:meName(),at:Date.now()});}
      }
    }
    if(a.type==='Vehicle'){
      a.vehicleType=V63.vehTypeSel||a.vehicleType||'Other vehicle';
      a.purchaseDate=cap.vpd||'';
      if(cap.reg)a.regId=cap.reg;
      a.notes=cap.vnotes||'';
    }
    save();
  }catch(e){console.warn('msv16',e);}
};
document.addEventListener('change',function(e){
  try{
    if(e.target&&e.target.id==='p16_partial'){var b=$('p16advbody');if(b)b.style.display=e.target.checked?'':'none';}
  }catch(err){DIAG.note(err,"35-v160-b16-insights-reports:1206");}
});

/* ================= Asset detail cards: Property & Vehicle (mock-ups S7 + docx §9/§20/§21) ================= */
function derived16(a,v,loans,word){
  var debt=0,rows='';
  loans.forEach(function(l){
    var b=accountBalAsOf(l.name,todayISO());if(!isFinite(b))return;
    debt+=Math.abs(b);
    rows+='<button class="fline" data-act="acc" data-n="'+esc(l.name)+'" style="width:100%;text-align:left"><span>Less '+esc(l.name)+'</span><b class="neg">\u2212 '+money(Math.abs(b))+'</b></button>';
  });
  return rows+'<div class="fline eq"><span><b>Net '+word+' position · derived</b></span><b class="'+(v-debt<0?'neg':'pos')+'">'+money(v-debt)+'</b></div>';
}
function assetCard16(a){
  var v=accountBalAsOf(a.name,todayISO()),lv=lastVal(a),st=V63.statusOf(a);
  var isProp=a.type==='Property';
  var loans=[];
  if(isProp){
    ((a.linkedLoans||[]).map(function(n){return a59(n);}).filter(Boolean)).forEach(function(l){if(loans.indexOf(l)<0)loans.push(l);});
    DB.accounts.forEach(function(l){if(isLoan(l)&&l.linkedAsset===a.name&&loans.indexOf(l)<0)loans.push(l);});
  }else{
    loans=DB.accounts.filter(function(l){return isLoan(l)&&l.linkedAsset===a.name;});
  }
  loans=loans.filter(function(l){return ownerHas(l.owner,whoOK());});
  var h='<div class="card"><h2>'+ico(isProp?'home':'car')+' '+(isProp?'Property':'Vehicle')+' <span class="sub">'+esc(a.owner||'')+(st!=='active'?' · '+esc(st):'')+'</span></h2>'
    +'<div style="padding:2px 0 8px"><div style="font-size:var(--fs-28);font-weight:800" class="'+(v<0?'neg':'')+'">'+money(v)+'</div>'
    +'<div class="help small" style="margin:2px 0 0">'+(isProp&&+a.ownPct>0&&+a.ownPct<100?(a.ownMode==='gross'?'Your/household share · '+a.ownPct+'% of full value':'Your/household share of the full value'):'Recorded value')+(lv?' · adjusted as at '+dLabelY(lv.date):' · purchase price')+'</div></div>'
    +'<div class="rows">';
  if(isProp){
    h+='<div class="fline"><span>Property type</span><b>'+esc(a.propType||'Other property')+'</b></div>';
    if(a.propUse)h+='<div class="fline"><span>Use</span><b>'+esc(a.propUse)+'</b></div>';
  }else{
    h+='<div class="fline"><span>Vehicle type</span><b>'+esc(a.vehicleType||'Other vehicle')+'</b></div>';
    if(a.regId)h+='<div class="fline"><span>Registration</span><b>'+esc(a.regId)+'</b></div>';
  }
  h+='<div class="fline"><span>Purchase price'+(a.purchaseDate?' · '+dLabelY(a.purchaseDate):'')+'</span><b>'+money(purchaseOf(a))+'</b></div>';
  if(a.notes)h+='<div class="fline"><span>Notes</span><b style="font-weight:600">'+esc(a.notes)+'</b></div>';
  h+='</div>';
  if(loans.length)h+='<div class="mgr-lb" style="margin-top:10px">Linked financing · kept separately under What I owe</div>'+derived16(a,v,loans,isProp?'property':'vehicle');
  h+='<div class="btnrow" style="margin-top:10px">'
    +'<button class="btn sm" data-act="valopen" data-n="'+esc(a.name)+'">'+ico('pencil')+' Update value</button>'
    +'<button class="btn sm ghost" data-act="v63dispose" data-n="'+esc(a.name)+'">'+ico('swap')+' '+(st==='active'?'Close / archive':'Reopen')+'</button>'
    +'<button class="btn sm ghost" data-act="v63edit" data-k="'+esc(a.name)+'">'+ico('sliders')+' Edit</button></div>';
  h+='<div class="help small" style="margin-top:8px">Value changes never create income, spending or cash flow. Selling does not close linked financing.</div></div>';
  /* property-linked activity (docx §7 — recorded via the transaction's Property tag) */
  if(isProp){
    var act=DB.txns.filter(function(t){return t.prop===a.name;}).sort(function(x,y){return x.date<y.date?1:-1;}).slice(0,5);
    if(act.length){
      h+='<div class="card"><h2>'+ico('receipt')+' Property-linked activity <span class="sub">rental &amp; operating</span></h2>'
        +act.map(function(t){var eff=flowEffect(t.type,t.amount);return '<button class="txn" data-act="txn" data-id="'+t.id+'"><span class="mid"><b>'+esc(t.category)+'</b><small>'+dLabelW(t.date)+' · '+esc(t.account)+'</small></span><span class="amt '+(eff>0?'pos':'neg')+'">'+(eff>0?'+':'−')+money(Math.abs(t.amount))+'</span></button>';}).join('')
        +'<button class="btn ghost sm" data-act="v63proplist" data-n="'+esc(a.name)+'" style="width:100%;margin-top:8px">View all</button></div>';
    }
  }
  return h;
}

