MGR_TITLE.v63remctr=ico('bell')+' Reminder centre'+info25('rem');
V56.mgr.v63remctr=function(){
  /* beta 25: one box per group, no status pills, no per-row button — tap a payment to open its account */
  var up=V63.calc.upcoming(90),td=todayISO();
  var g={'Overdue':function(x){return x.dl<0;},'Due today':function(x){return x.dl===0;},'Due soon':function(x){return x.dl>0&&x.dl<=3;},'Upcoming':function(x){return x.dl>3;}};
  function row(x){return V63.UPROW(x);}

  function box(title,cls,n,body){return '<div class="rem25box '+cls+'"><div class="rem25h"><span>'+title+'</span>'+(n?'<span class="n">'+n+'</span>':'')+'</div>'+body+'</div>';}
  var h='';
  Object.keys(g).forEach(function(k){
    var list=up.filter(g[k]);if(!list.length)return;
    h+=box(k,k==='Overdue'?'bad':(k==='Upcoming'?'':'warn'),list.length,list.map(row).join(''));
  });
  var done='';
  dueList(45).forEach(function(x){if(x.stillDue<0.005&&x.status==='paid')done+='<div class="rem25row"><span class="nm"><b>'+esc(x.name)+'</b><small>Credit card · statement paid</small></span></div>';});
  var lim=addDaysISO(td,-45);
  DB.txns.slice().sort(function(x,y){return x.date<y.date?1:-1;}).some(function(t){
    if(t.date<lim)return true;
    if(t.type==='Transfer'&&t.to){var a=a59(t.to);if(a&&isLoan(a))done+='<div class="rem25row"><span class="nm"><b>'+esc(t.to)+'</b><small>Repayment recorded '+dLabelW(t.date)+'</small></span><span class="amt">'+money(t.amount)+'</span></div>';}
    return false;
  });
  if(done)h+=box('Completed','ok',0,done);
  if(!h)h='<div class="rem25empty">No payments due in the next 90 days. Nothing overdue.</div>';
  $('mgrBody').innerHTML=h;
};
