      +[['m','Monthly'],['f','Fortnightly'],['w','Weekly'],['q','Quarterly'],['y','Yearly']].map(function(o){return '<option value="'+o[0]+'"'+((a.freq||'m')===o[0]?' selected':'')+'>'+o[1]+'</option>';}).join('')+'</select>'
      +'<div class="mgr-lb">Regular instalment (optional)</div><input class="fin" id="rs16inst" inputmode="decimal" value="'+(a.instalment>0?a.instalment:'')+'" placeholder="Prefills Record repayment" style="margin-bottom:7px">'
