/* ---------- 2 · Status: automated health, read-only ---------- */
function paintStatus(){
  var b=$('ds22Status');if(!b)return;
  var old=b.previousElementSibling;if(old&&old.classList.contains('ds-status'))old.classList.add('ds22-hide');
  var m=storageMode(),st=statusState59(),v=m59(),bs=bkState59();
  var hic=st.cls==='ok'?'check':(st.cls==='bad'?'cloudoff':(st.cls==='warn'?'warn':(m==='device'?'phone':'cloud')));
  var why=st.why;
  if(m==='device'&&bs==='ok')why='Your data stays on this device and your latest changes are in your last backup file.';
  var ttl=st.text;if(m==='device')ttl=bs==='ok'?'Saved on this device · backed up':'Saved on this device';
  var h='<div class="ds22-hero '+(st.cls||'')+'"><span class="hic">'+ico(hic)+'</span><span><b>'+esc(ttl)+'</b><small>'+esc(why)+'</small></span></div>';
  /* 1 — safety snapshots: always automatic */
  var n=(window.BK&&BK.log)?BK.log.length:0;
  h+=chk('', 'shield','Safety snapshots · automatic',n?(n+' kept · latest '+when(BK.log[0].at)):'Taken after every change');
  /* 2 — where the data lives (change = progressive disclosure) */
  h+=chk('info',m==='device'?'phone':(m==='household'?'users':'cloud'),'Where your data lives',esc(STG_L[m]||m),'<button class="aulink" data-act="ds22stg">'+(D22.stgOpen?'Done':'Change')+'</button>');
  /* 3 — backup file or sync */
  if(m==='household'){
    var on=!!(window.FB&&FB.user&&DB.meta.cloudSyncOn);
    h+=chk(on?(st.cls==='bad'?'bad':''):'bad',on?'refresh':'cloudoff','Last sync',on?(DB.meta.cloudPushedAt?when(DB.meta.cloudPushedAt):'Waiting for first sync'):'Not signed in');
  }else{
    var bkv=v.backupAt?when(v.backupAt):'None yet';
    var cls=bs==='ok'?'':'warn';
    h+=chk(cls,bs==='ok'?'check':'warn',m==='device'?'Backup file':'Last backup',bkv+(bs==='due'?' · changes since':''));
  }
  /* actions */
  h+='<div class="ds22-acts">';
  if(m==='household')h+='<button class="btn" data-act="fbsync">'+ico('refresh')+' Sync now</button>';
  h+='</div>';
  b.innerHTML=h;
  var w=$('ds22Stg');if(w)w.hidden=!D22.stgOpen;
}

/* ---------- 3 · Preferences: only real, low-risk choices ---------- */
