    +row('cal','Remind me','','<select class="fin" style="width:auto" onchange="remCfg().days=+this.value;touch();V63.bellBadge()">'
      +[1,3,5,7].map(function(d){return '<option value="'+d+'"'+(+c.days===d?' selected':'')+'>'+d+' day'+(d>1?'s':'')+' before</option>';}).join('')+'</select>')
