    s.dek=dek;
    if(s.from==='boot'&&V57.encRec)return decStr(V57.encRec,k).then(function(json){V57.key=k;V57.bootJson=json;V57.dekRaw=dek;});
    V57.key=k;V57.dekRaw=dek;
