  return (s.pw?pwWrap(s.pw,dek).then(function(w){L.push(w);}):Promise.resolve()).then(function(){
    return s.reg?srvWrap(s.reg.secret,dek).then(function(w){L.push(w);}):null;
  }).then(function(){return L;});
