  if(from==='boot'){lockHide();var cb=V57.bootCb;V57.bootCb=null;if(cb)cb(V57.bootJson);V57.bootJson=null;return;}
  if(s.kind!=='protect')lockHide();
  try{B3.renderPrivSub();}catch(e){}
